window.QBANK = window.QBANK || {};
window.QBANK["sma-sejarah"] = {
  level: "SMA", subject: "Sejarah", duration: 900,
  questions: [
    { q: "Raja Kutai yang namanya diabadikan dalam Prasasti Yupa sebagai raja yang dermawan dan pernah mengadakan upacara pengorbanan adalah ....", options: ["Mulawarman", "Kudungga", "Aswawarman", "Purnawarman"], answer: 0, solution: "1. Prasasti Yupa adalah peninggalan Kerajaan Kutai Martadipura di Kalimantan Timur, kerajaan Hindu tertua di Indonesia. 2. Yupa menceritakan Raja Mulawarman yang dermawan dan mengadakan selamatan (upacara korban) dengan menghadiahkan 20.000 ekor sapi kepada kaum brahmana. 3. Kudungga adalah pendiri kerajaan dan Aswawarman adalah ayah Mulawarman, sedangkan Purnawarman adalah raja Tarumanagara. 4. Jadi jawabannya Mulawarman." },
    { q: "Prasasti Tugu peninggalan Tarumanagara menceritakan Raja Purnawarman memerintahkan penggalian dua buah sungai, yaitu ....", options: ["Musi dan Batanghari", "Bengawan Solo dan Brantas", "Ciliwung dan Cisadane", "Gomati dan Candrabhaga"], answer: 3, solution: "1. Prasasti Tugu ditemukan di daerah Tugu, Jakarta Utara, peninggalan Kerajaan Tarumanagara. 2. Isinya: Raja Purnawarman memerintahkan penggalian Sungai Gomati dan Candrabhaga untuk pengairan sawah dan mencegah banjir. 3. Sungai Musi dan Batanghari terkait wilayah Sriwijaya di Sumatera, sedangkan Bengawan Solo dan Brantas di Jawa Timur. 4. Jadi jawabannya Gomati dan Candrabhaga." },
    { q: "Raja Tarumanagara yang paling terkenal dan namanya disebut dalam tujuh prasasti adalah ....", options: ["Mulawarman", "Balaputradewa", "Sanjaya", "Purnawarman"], answer: 3, solution: "1. Tarumanagara adalah kerajaan Hindu di Jawa Barat yang berkembang pada abad ke-5 M. 2. Raja terbesarnya adalah Purnawarman yang namanya tercantum dalam tujuh prasasti: Ciaruteun, Kebon Kopi, Tugu, Cidanghiang, Jambu, Pasir Awi, dan Muara Cianten. 3. Mulawarman adalah raja Kutai, Balaputradewa raja Sriwijaya, dan Sanjaya raja Mataram Kuno. 4. Jadi jawabannya Purnawarman." },
    { q: "Menurut Prasasti Kedukan Bukit yang berangka tahun 683 M, pendiri Kerajaan Sriwijaya adalah ....", options: ["Dapunta Hyang Sri Jayanasa", "Balaputradewa", "Adityawarman", "Rajendra Chola"], answer: 0, solution: "1. Prasasti Kedukan Bukit ditemukan di Palembang dan berangka tahun 683 M. 2. Isinya menceritakan Dapunta Hyang Sri Jayanasa melakukan perjalanan suci (siddhayatra) dengan 20.000 pasukan lalu mendirikan Sriwijaya. 3. Balaputradewa adalah raja Sriwijaya abad ke-9, Adityawarman raja Malayupura, sedangkan Rajendra Chola justru raja yang menyerang Sriwijaya. 4. Jadi jawabannya Dapunta Hyang Sri Jayanasa." },
    { q: "Sriwijaya dikenal sebagai kerajaan maritim karena kekuatan utamanya bertumpu pada ....", options: ["pertanian padi yang subur", "perdagangan dan pelayaran", "pertambangan emas", "industri kerajinan"], answer: 1, solution: "1. Sriwijaya berpusat di Palembang dan menguasai jalur pelayaran Selat Malaka. 2. Kekuatannya berasal dari armada laut yang menguasai perdagangan, terutama rempah, antara India, Tiongkok, dan Nusantara. 3. Karena bertumpu pada laut dan dagang, Sriwijaya dijuluki kerajaan maritim, bukan kerajaan agraris. 4. Jadi jawabannya perdagangan dan pelayaran." },
    { q: "Candi Borobudur yang megah dibangun pada masa pemerintahan wangsa ....", options: ["Isyana", "Sanjaya", "Syailendra", "Rajasa"], answer: 2, solution: "1. Borobudur di Magelang adalah candi Buddha terbesar di dunia peninggalan Mataram Kuno. 2. Candi ini dibangun pada abad ke-9 M oleh wangsa Syailendra yang beragama Buddha, diperkirakan pada masa Raja Samaratungga. 3. Wangsa Sanjaya beragama Hindu (membangun Prambanan), sedangkan wangsa Isyana dan Rajasa berkuasa di Jawa Timur. 4. Jadi jawabannya Syailendra." },
    { q: "Candi Prambanan, candi Hindu terbesar di Indonesia, mulai dibangun pada masa pemerintahan ....", options: ["Samaratungga", "Balitung", "Rakai Pikatan", "Rakai Kayuwangi"], answer: 3, solution: "1. Candi Prambanan di perbatasan Yogyakarta-Klaten dibangun sekitar abad ke-9 M dan dipersembahkan untuk Trimurti (Brahma, Wisnu, Siwa). 2. Pembangunannya dimulai pada masa Rakai Pikatan dari wangsa Sanjaya yang beragama Hindu. 3. Samaratungga adalah raja Syailendra (pembangun Borobudur), sedangkan Balitung dan Rakai Kayuwangi adalah raja Mataram Kuno sesudahnya. 4. Jadi jawabannya Rakai Pikatan." },
    { q: "Raja Singasari yang melancarkan Ekspedisi Pamalayu ke Sumatera pada tahun 1275 adalah ....", options: ["Kertanegara", "Ken Arok", "Anusapati", "Jayakatwang"], answer: 0, solution: "1. Ekspedisi Pamalayu (1275) adalah ekspedisi militer Singasari ke Kerajaan Melayu Dharmasraya di Sumatera. 2. Ekspedisi ini diperintahkan Raja Kertanegara untuk menjalin persekutuan dan membendung pengaruh Mongol di bawah Kubilai Khan. 3. Ken Arok adalah pendiri Singasari, Anusapati adalah anaknya, sedangkan Jayakatwang justru raja Kediri yang menyerang Singasari. 4. Jadi jawabannya Kertanegara." },
    { q: "Tokoh yang mengucapkan Sumpah Palapa pada tahun 1336 adalah ....", options: ["Hayam Wuruk", "Gajah Mada", "Raden Wijaya", "Mpu Prapanca"], answer: 1, solution: "1. Sumpah Palapa (1336) berisi tekad untuk menyatukan Nusantara di bawah panji Majapahit. 2. Sumpah ini diucapkan oleh Mahapatih Gajah Mada ketika ia dilantik menjadi patih amangkubumi. 3. Hayam Wuruk adalah raja Majapahit yang berkuasa saat itu, Raden Wijaya adalah pendiri Majapahit, dan Mpu Prapanca adalah pengarang Negarakertagama. 4. Jadi jawabannya Gajah Mada." },
    { q: "Kitab Negarakertagama yang menjadi sumber utama sejarah kejayaan Majapahit dikarang oleh ....", options: ["Mpu Tantular", "Mpu Kanwa", "Mpu Prapanca", "Mpu Sedah"], answer: 2, solution: "1. Negarakertagama (1365) menceritakan kejayaan Majapahit pada masa Raja Hayam Wuruk. 2. Kitab ini dikarang oleh Mpu Prapanca. 3. Mpu Tantular mengarang Sutasoma (sumber semboyan Bhinneka Tunggal Ika), Mpu Kanwa mengarang Arjunawiwaha, dan Mpu Sedah mengarang Bharatayudha. 4. Jadi jawabannya Mpu Prapanca." },
    { q: "Kerajaan Islam pertama di Nusantara adalah ....", options: ["Kesultanan Aceh Darussalam", "Kesultanan Demak", "Kesultanan Mataram", "Samudra Pasai"], answer: 3, solution: "1. Islam masuk ke Nusantara melalui para pedagang dan pertama kali berkembang di pesisir Sumatera. 2. Kerajaan Islam tertua di Nusantara adalah Samudra Pasai di Aceh Utara yang berdiri pada abad ke-13. 3. Aceh Darussalam, Demak, dan Mataram Islam muncul kemudian setelah Pasai. 4. Jadi jawabannya Samudra Pasai." },
    { q: "Pendiri Kerajaan Samudra Pasai yang bergelar Sultan Malikussaleh adalah ....", options: ["Malikussaleh", "Iskandar Muda", "Sultan Trenggana", "Fatahillah"], answer: 0, solution: "1. Samudra Pasai didirikan pada abad ke-13 di pesisir utara Aceh. 2. Pendirinya adalah Meurah Silu yang setelah masuk Islam bergelar Sultan Malikussaleh (wafat 1297). 3. Iskandar Muda adalah sultan Aceh Darussalam, Sultan Trenggana adalah raja Demak, dan Fatahillah adalah panglima Demak. 4. Jadi jawabannya Malikussaleh." },
    { q: "Kesultanan Demak sebagai kerajaan Islam pertama di Pulau Jawa didirikan oleh ....", options: ["Sunan Giri", "Sultan Trenggana", "Raden Patah", "Fatahillah"], answer: 2, solution: "1. Setelah Majapahit runtuh, pusat kekuasaan Islam di Jawa berdiri di Demak pada akhir abad ke-15. 2. Pendirinya adalah Raden Patah (putra Brawijaya V, raja terakhir Majapahit). 3. Sultan Trenggana adalah raja terbesar Demak pada generasi berikutnya, sedangkan Sunan Giri dan Fatahillah adalah tokoh penyebar Islam. 4. Jadi jawabannya Raden Patah." },
    { q: "Fatahillah berhasil merebut Sunda Kelapa dari Portugis pada tahun 1527 atas perintah Sultan Demak, yaitu ....", options: ["Raden Patah", "Sultan Hadiwijaya", "Sultan Trenggana", "Sunan Gunung Jati"], answer: 2, solution: "1. Pada masa kejayaannya, Demak melakukan ekspedisi untuk mengusir Portugis dari pesisir barat Jawa. 2. Fatahillah merebut Sunda Kelapa pada 22 Juni 1527 (diperingati sebagai hari jadi Jakarta) atas perintah Sultan Trenggana. 3. Raden Patah adalah pendiri Demak, Hadiwijaya adalah raja Pajang, dan Sunan Gunung Jati adalah wali penyebar Islam di Cirebon. 4. Jadi jawabannya Sultan Trenggana." },
    { q: "Raja Mataram Islam yang dua kali menyerang Batavia (1628 dan 1629) untuk mengusir VOC adalah ....", options: ["Panembahan Senopati", "Amangkurat I", "Pakubuwono II", "Sultan Agung"], answer: 3, solution: "1. Mataram Islam mencapai puncak kejayaan pada masa Sultan Agung (1613-1645). 2. Ia menyerang Batavia pada tahun 1628 dan 1629, tetapi gagal karena benteng VOC kuat dan pasukannya kekurangan perbekalan. 3. Panembahan Senopati adalah pendiri Mataram, sedangkan Amangkurat I dan Pakubuwono II adalah raja-raja sesudahnya. 4. Jadi jawabannya Sultan Agung." },
    { q: "Pendiri Kerajaan Mataram Islam yang berpusat di Kotagede, Yogyakarta, adalah ....", options: ["Sutawijaya", "Sultan Agung", "Amangkurat I", "Raden Patah"], answer: 0, solution: "1. Mataram Islam didirikan pada akhir abad ke-16 di pedalaman Jawa. 2. Pendirinya adalah Sutawijaya yang bergelar Panembahan Senopati. 3. Sultan Agung adalah cucunya sekaligus raja terbesar Mataram, Amangkurat I adalah anak Sultan Agung, dan Raden Patah adalah pendiri Demak. 4. Jadi jawabannya Sutawijaya." },
    { q: "Sultan Hasanuddin, raja Gowa-Tallo yang gigih melawan VOC, mendapat julukan dari Belanda ....", options: ["Singa dari Timur", "Ayam Jantan dari Timur", "Harimau dari Timur", "Garuda dari Timur"], answer: 1, solution: "1. Sultan Hasanuddin memerintah Gowa pada 1653-1669 dan dengan gigih melawan monopoli perdagangan VOC. 2. Kegigihan dan keberaniannya membuat Belanda menjulukinya Ayam Jantan dari Timur (De Haantjes van Het Oosten). 3. Julukan-julukan lain pada pilihan jawaban tidak pernah disematkan kepadanya. 4. Jadi jawabannya Ayam Jantan dari Timur." },
    { q: "Perjanjian Bongaya (1667) ditandatangani Sultan Hasanuddin setelah Gowa kalah perang melawan ....", options: ["Portugis", "Spanyol", "VOC", "Inggris"], answer: 2, solution: "1. VOC di bawah Laksamana Cornelis Speelman menyerang Gowa karena menentang monopoli perdagangan rempah. 2. Setelah kalah, Sultan Hasanuddin terpaksa menandatangani Perjanjian Bongaya pada 18 November 1667 yang sangat merugikan Gowa. 3. Portugis dan Spanyol sudah tersingkir dari Sulawesi, sedangkan Inggris belum berpengaruh di kawasan itu. 4. Jadi jawabannya VOC." },
    { q: "Sultan Ternate yang berhasil mengusir Portugis dari Maluku pada 1575 dan memperluas wilayahnya hingga Filipina adalah ....", options: ["Sultan Iskandar Muda", "Sultan Nuku", "Sultan Ageng Tirtayasa", "Sultan Baabullah"], answer: 3, solution: "1. Pada abad ke-16, Ternate bersaing dengan Portugis memperebutkan perdagangan rempah di Maluku. 2. Sultan Baabullah (1570-1583) mengepung dan mengusir Portugis dari Maluku pada 1575, lalu memperluas kekuasaan Ternate hingga Filipina selatan. 3. Sultan Nuku adalah sultan Tidore abad ke-18, Iskandar Muda adalah sultan Aceh, dan Sultan Ageng Tirtayasa adalah sultan Banten. 4. Jadi jawabannya Sultan Baabullah." },
    { q: "VOC (Vereenigde Oostindische Compagnie) didirikan di Belanda pada tahun ....", options: ["1602", "1596", "1619", "1799"], answer: 0, solution: "1. Sebelum VOC berdiri, banyak perusahaan dagang Belanda saling bersaing di Nusantara. 2. Atas usul Johan van Oldenbarnevelt, perusahaan-perusahaan itu digabung menjadi VOC pada 20 Maret 1602. 3. Tahun 1596 adalah kedatangan Cornelis de Houtman, 1619 adalah pendirian Batavia, dan 1799 adalah pembubaran VOC. 4. Jadi jawabannya 1602." },
    { q: "Hak-hak istimewa yang diberikan pemerintah Belanda kepada VOC, seperti mencetak uang dan memiliki tentara, disebut ....", options: ["devide et impera", "hak oktroi", "cultuurstelsel", "hak ekstirpasi"], answer: 1, solution: "1. Untuk memuluskan monopoli dagang, VOC diberi wewenang luar biasa oleh parlemen Belanda. 2. Hak istimewa ini disebut hak oktroi, meliputi: mencetak uang, memiliki tentara, menyatakan perang dan damai, serta mengangkat pegawai. 3. Devide et impera adalah politik adu domba, cultuurstelsel adalah tanam paksa, dan ekstirpasi adalah pemusnahan tanaman rempah. 4. Jadi jawabannya hak oktroi." },
    { q: "Gubernur Jenderal VOC yang menghancurkan Jayakarta dan mendirikan kota Batavia pada 1619 adalah ....", options: ["Pieter Both", "Cornelis Speelman", "Jan Pieterszoon Coen", "Herman Daendels"], answer: 2, solution: "1. VOC membutuhkan pusat pemerintahan yang kuat di Jawa. 2. Jan Pieterszoon Coen menghancurkan Jayakarta dan membangun Batavia pada tahun 1619 sebagai pusat kekuasaan VOC. 3. Pieter Both adalah gubernur jenderal pertama VOC, Speelman adalah penakluk Gowa, dan Daendels adalah gubernur jenderal pada masa kekuasaan Perancis. 4. Jadi jawabannya Jan Pieterszoon Coen." },
    { q: "Sistem tanam paksa (Cultuurstelsel) yang diberlakukan pada tahun 1830 dicetuskan oleh Gubernur Jenderal ....", options: ["Herman Daendels", "Thomas Raffles", "Eduard Douwes Dekker", "Johannes van den Bosch"], answer: 3, solution: "1. Belanda mengalami krisis keuangan setelah Perang Diponegoro dan lepasnya Belgia. 2. Gubernur Jenderal Johannes van den Bosch mencetuskan Cultuurstelsel (1830): rakyat wajib menanam tanaman ekspor di seperlima tanahnya atau bekerja 66 hari. 3. Daendels membangun Jalan Raya Pos, Raffles menulis History of Java, sedangkan Douwes Dekker justru pengkritik tanam paksa. 4. Jadi jawabannya Johannes van den Bosch." },
    { q: "Novel Max Havelaar yang mengkritik tajam kekejaman tanam paksa ditulis oleh ....", options: ["Multatuli", "Tirto Adhi Soerjo", "H.O.S. Tjokroaminoto", "Ki Hajar Dewantara"], answer: 0, solution: "1. Eduard Douwes Dekker pernah menjadi asisten residen di Lebak dan menyaksikan langsung penderitaan rakyat akibat tanam paksa. 2. Ia menulis novel Max Havelaar (1860) dengan nama pena Multatuli yang mengguncang opini publik Belanda hingga tanam paksa dihapus bertahap. 3. Tirto Adhi Soerjo adalah bapak pers Indonesia, Tjokroaminoto adalah pemimpin Sarekat Islam, dan Ki Hajar Dewantara adalah tokoh pendidikan. 4. Jadi jawabannya Multatuli." },
    { q: "Tiga program pokok Politik Etis yang dicanangkan Ratu Wilhelmina pada tahun 1901 adalah ....", options: ["industri, investasi, dan infrastruktur", "militer, moneter, dan migrasi", "irigasi, emigrasi, dan edukasi", "perdagangan, perkebunan, dan pelayaran"], answer: 2, solution: "1. Politik Etis (1901) adalah politik balas budi Belanda atas keuntungan besar dari tanam paksa. 2. Programnya dikenal dengan tiga serangkai: irigasi (pengairan sawah), emigrasi (perpindahan penduduk/transmigrasi), dan edukasi (pendidikan). 3. Pilihan lain mencampurkan istilah modern yang tidak terkait dengan Politik Etis. 4. Jadi jawabannya irigasi, emigrasi, dan edukasi." },
    { q: "Belanda menyerah tanpa syarat kepada Jepang dalam Perjanjian Kalijati pada tanggal ....", options: ["17 Agustus 1945", "9 Maret 1942", "8 Maret 1942", "15 Agustus 1945"], answer: 2, solution: "1. Jepang mendarat di Jawa pada awal 1942 dan mendesak pertahanan Belanda. 2. Pada 8 Maret 1942 Belanda menandatangani penyerahan tanpa syarat di Kalijati, Subang, sehingga Indonesia diduduki Jepang selama 3,5 tahun. 3. Tanggal 17 Agustus 1945 adalah proklamasi kemerdekaan dan 15 Agustus 1945 adalah Jepang menyerah kepada Sekutu. 4. Jadi jawabannya 8 Maret 1942." },
    { q: "Organisasi bentukan Jepang pada tahun 1943 yang dipimpin oleh Empat Serangkai (Soekarno, Hatta, Ki Hajar Dewantara, K.H. Mas Mansyur) adalah ....", options: ["PETA", "Jawa Hokokai", "Seinendan", "Putera"], answer: 3, solution: "1. Jepang membentuk organisasi untuk memobilisasi rakyat Indonesia mendukung perang Asia Timur Raya. 2. Putera (Pusat Tenaga Rakyat, 1943) dipimpin Empat Serangkai: Soekarno, Hatta, Ki Hajar Dewantara, dan K.H. Mas Mansyur. 3. PETA adalah tentara sukarela, Jawa Hokokai adalah pengganti Putera (1944), dan Seinendan adalah barisan pemuda. 4. Jadi jawabannya Putera." },
    { q: "Organisasi Budi Utomo yang menjadi tonggak Kebangkitan Nasional didirikan pada ....", options: ["20 Mei 1908", "28 Oktober 1928", "1 Juni 1945", "17 Agustus 1945"], answer: 0, solution: "1. Budi Utomo didirikan oleh para pelajar STOVIA di Jakarta. 2. Tanggal pendiriannya, 20 Mei 1908, diperingati sebagai Hari Kebangkitan Nasional. 3. Tanggal 28 Oktober 1928 adalah Sumpah Pemuda, 1 Juni 1945 adalah lahirnya Pancasila, dan 17 Agustus 1945 adalah proklamasi kemerdekaan. 4. Jadi jawabannya 20 Mei 1908." },
    { q: "Ketua pertama organisasi Budi Utomo adalah ....", options: ["Wahidin Sudirohusodo", "dr. Sutomo", "Douwes Dekker", "Tjipto Mangoenkoesoemo"], answer: 1, solution: "1. Gagasan pendirian Budi Utomo dicetuskan oleh dr. Wahidin Sudirohusodo. 2. Namun yang menjadi ketua pertama adalah dr. Sutomo (Soetomo). 3. Wahidin adalah pencetus ide, Douwes Dekker adalah tokoh Indische Partij, dan Tjipto Mangoenkoesoemo adalah tokoh pergerakan yang lebih radikal. 4. Jadi jawabannya dr. Sutomo." },
    { q: "Ikrar Sumpah Pemuda yang diucapkan pada 28 Oktober 1928 berisi ....", options: ["satu nusa, satu bangsa, satu bahasa: Belanda", "bertanah air satu, berbangsa satu, berbahasa satu: Indonesia", "merdeka, bersatu, berdaulat", "satu tujuan, satu tekad, satu perjuangan"], answer: 1, solution: "1. Sumpah Pemuda adalah hasil Kongres Pemuda II yang berlangsung di Jakarta. 2. Ikrarnya: bertanah air satu tanah air Indonesia, berbangsa satu bangsa Indonesia, dan menjunjung bahasa persatuan bahasa Indonesia. 3. Pilihan lain bukan rumusan ikrar yang diucapkan pada 28 Oktober 1928. 4. Jadi jawabannya bertanah air satu, berbangsa satu, berbahasa satu: Indonesia." },
    { q: "Lagu Indonesia Raya pertama kali diperdengarkan pada Kongres Pemuda II oleh penciptanya, yaitu ....", options: ["Ismail Marzuki", "Cornel Simanjuntak", "Kusbini", "W.R. Supratman"], answer: 3, solution: "1. Pada penutupan Kongres Pemuda II (28 Oktober 1928), diperdengarkan sebuah lagu kebangsaan. 2. Lagu Indonesia Raya dimainkan dengan biola oleh penciptanya sendiri, Wage Rudolf Supratman. 3. Ismail Marzuki, Cornel Simanjuntak, dan Kusbini adalah komponis lagu perjuangan dari generasi kemudian. 4. Jadi jawabannya W.R. Supratman." },
    { q: "Partai Nasional Indonesia (PNI) didirikan oleh Soekarno di Bandung pada tahun ....", options: ["1927", "1908", "1912", "1928"], answer: 0, solution: "1. PNI adalah partai politik pertama yang berhaluan nasionalisme radikal dan non-kooperasi terhadap Belanda. 2. Partai ini didirikan Soekarno di Bandung pada 4 Juli 1927. 3. Tahun 1908 adalah berdirinya Budi Utomo, 1912 adalah Sarekat Islam, dan 1928 adalah Sumpah Pemuda. 4. Jadi jawabannya 1927." },
    { q: "Ketua BPUPKI (Badan Penyelidik Usaha-usaha Persiapan Kemerdekaan Indonesia) adalah ....", options: ["Ir. Soekarno", "Moh. Hatta", "Radjiman Wedyodiningrat", "Mr. Soepomo"], answer: 1, solution: "1. BPUPKI dibentuk Jepang pada 29 April 1945 untuk menyelidiki usaha-usaha persiapan kemerdekaan Indonesia. 2. Ketuanya adalah dr. K.R.T. Radjiman Wedyodiningrat. 3. Soekarno dan Hatta justru menjadi ketua dan wakil ketua PPKI, sedangkan Soepomo adalah anggota BPUPKI yang merumuskan UUD. 4. Jadi jawabannya Radjiman Wedyodiningrat." },
    { q: "Hasil sidang PPKI pada tanggal 18 Agustus 1945 adalah ....", options: ["memproklamasikan kemerdekaan Indonesia", "mengesahkan UUD 1945 serta memilih Soekarno-Hatta sebagai presiden dan wakil presiden", "membentuk BPUPKI", "mengikrarkan Sumpah Pemuda"], answer: 1, solution: "1. Sehari setelah proklamasi, PPKI bersidang di Jakarta. 2. Hasilnya: mengesahkan UUD 1945 sebagai konstitusi negara dan memilih Ir. Soekarno sebagai presiden serta Drs. Moh. Hatta sebagai wakil presiden. 3. Proklamasi sudah terjadi pada 17 Agustus, BPUPKI dibentuk sebelumnya, dan Sumpah Pemuda terjadi pada 1928. 4. Jadi jawabannya mengesahkan UUD 1945 serta memilih Soekarno-Hatta sebagai presiden dan wakil presiden." },
    { q: "Naskah teks proklamasi yang dibacakan Soekarno diketik oleh ....", options: ["Ir. Soekarno", "Drs. Moh. Hatta", "B.M. Diah", "Sayuti Melik"], answer: 3, solution: "1. Teks proklamasi dirumuskan oleh Soekarno, Hatta, dan Ahmad Soebardjo di rumah Laksamana Maeda pada dini hari 17 Agustus 1945. 2. Naskah tulisan tangan Soekarno kemudian diketik oleh Sayuti Melik. 3. B.M. Diah adalah wartawan yang menyimpan naskah asli tulisan tangan Soekarno. 4. Jadi jawabannya Sayuti Melik." },
    { q: "Agresi Militer Belanda II yang menyerang Yogyakarta dan menangkap Soekarno-Hatta dilancarkan pada ....", options: ["19 Desember 1948", "21 Juli 1947", "27 Desember 1949", "10 November 1945"], answer: 0, solution: "1. Belanda melanggar Perjanjian Renville dan kembali menyerang Republik Indonesia. 2. Agresi Militer II (Operatie Kraai) dilancarkan pada 19 Desember 1948: Yogyakarta diduduki, Soekarno-Hatta ditangkap dan diasingkan. 3. Tanggal 21 Juli 1947 adalah Agresi Militer I, 27 Desember 1949 adalah penyerahan kedaulatan, dan 10 November 1945 adalah pertempuran Surabaya. 4. Jadi jawabannya 19 Desember 1948." },
    { q: "Hasil Konferensi Meja Bundar (KMB) di Den Haag tahun 1949 adalah ....", options: ["Belanda mengakui RI secara de facto atas Jawa dan Sumatera", "Belanda mengakui kedaulatan Indonesia sepenuhnya", "Indonesia menjadi negara bagian Malaysia", "Belanda menarik pasukannya tanpa syarat apa pun"], answer: 1, solution: "1. KMB berlangsung pada 23 Agustus-2 November 1949 sebagai perundingan penentuan kedaulatan. 2. Hasilnya: Belanda mengakui kedaulatan Indonesia sepenuhnya dan penyerahan kedaulatan dilaksanakan pada 27 Desember 1949. 3. Pengakuan de facto atas Jawa dan Sumatera adalah hasil Perjanjian Linggarjati 1946, bukan KMB. 4. Jadi jawabannya Belanda mengakui kedaulatan Indonesia sepenuhnya." },
    { q: "Isi pokok Perjanjian Linggarjati (1946) adalah ....", options: ["Belanda mengakui kedaulatan penuh Indonesia", "Belanda mengakui RI secara de facto atas Jawa, Sumatera, dan Madura", "Indonesia menjadi Republik Indonesia Serikat", "gencatan senjata tanpa pengakuan wilayah"], answer: 1, solution: "1. Perjanjian Linggarjati ditandatangani pada 15 November 1946 (diratifikasi 25 Maret 1947). 2. Isi pokoknya: Belanda mengakui secara de facto Republik Indonesia dengan wilayah kekuasaan meliputi Jawa, Sumatera, dan Madura. 3. Pengakuan kedaulatan penuh baru terjadi melalui KMB 1949 dan RIS adalah hasil KMB. 4. Jadi jawabannya Belanda mengakui RI secara de facto atas Jawa, Sumatera, dan Madura." },
    { q: "Isi pokok Dekrit Presiden 5 Juli 1959 adalah ....", options: ["pembubaran DPR hasil pemilu 1955", "kembali ke UUD 1945 dan pembubaran Konstituante", "pembentukan MPRS", "penerapan kembali demokrasi liberal"], answer: 1, solution: "1. Konstituante hasil pemilu 1955 gagal menyusun UUD baru karena mengalami deadlock. 2. Soekarno mengeluarkan Dekrit 5 Juli 1959 yang berisi: kembali ke UUD 1945, pembubaran Konstituante, serta pembentukan MPRS dan DPAS. 3. Dekrit ini menandai dimulainya Demokrasi Terpimpin, bukan kembalinya demokrasi liberal. 4. Jadi jawabannya kembali ke UUD 1945 dan pembubaran Konstituante." },
    { q: "Latar belakang dikeluarkannya Dekrit Presiden 5 Juli 1959 adalah ....", options: ["kegagalan Konstituante menyusun UUD karena deadlock", "pemberontakan PRRI/Permesta", "krisis ekonomi yang parah", "tekanan dari PKI"], answer: 0, solution: "1. Konstituante bertugas menyusun UUD pengganti UUDS 1950. 2. Konstituante mengalami kemacetan (deadlock) karena tidak mencapai kata sepakat, terutama mengenai dasar negara. 3. Untuk mengatasi kebuntuan ketatanegaraan itu, Soekarno mengeluarkan Dekrit 5 Juli 1959. 4. Jadi jawabannya kegagalan Konstituante menyusun UUD karena deadlock." },
    { q: "Peristiwa G30S/PKI yang menewaskan para perwira TNI Angkatan Darat terjadi pada ....", options: ["11 Maret 1966", "1 Juni 1945", "30 September 1965", "5 Juli 1959"], answer: 2, solution: "1. Pada malam 30 September hingga 1 Oktober 1965 terjadi penculikan dan pembunuhan terhadap para perwira TNI Angkatan Darat. 2. Tujuh perwira gugur (termasuk 6 jenderal) dan dimakamkan di Lubang Buaya; peristiwa ini diperingati setiap tanggal 30 September. 3. Tanggal 11 Maret 1966 adalah Supersemar, 1 Juni 1945 adalah lahirnya Pancasila, dan 5 Juli 1959 adalah Dekrit Presiden. 4. Jadi jawabannya 30 September 1965." },
    { q: "Rencana pembangunan lima tahunan pada masa Orde Baru disebut ....", options: ["Propenas", "GBHN", "Repelita", "Manipol"], answer: 2, solution: "1. Orde Baru memprioritaskan pembangunan ekonomi nasional. 2. Rencana pembangunan disusun dalam Rencana Pembangunan Lima Tahun (Repelita), dimulai dengan Pelita I pada tahun 1969. 3. Propenas adalah program era reformasi, GBHN adalah garis-garis besar haluan negara, dan Manipol adalah doktrin politik masa Demokrasi Terpimpin. 4. Jadi jawabannya Repelita." },
    { q: "Presiden Soeharto mengundurkan diri dari jabatannya pada tanggal ....", options: ["11 Maret 1966", "12 Mei 1998", "21 Mei 1999", "21 Mei 1998"], answer: 3, solution: "1. Krisis moneter 1997-1998 memicu krisis ekonomi dan politik serta gelombang demonstrasi mahasiswa. 2. Soeharto menyatakan berhenti sebagai presiden pada 21 Mei 1998 dan digantikan oleh Wakil Presiden B.J. Habibie. 3. Tanggal 12 Mei 1998 adalah Tragedi Trisakti dan 11 Maret 1966 adalah Supersemar. 4. Jadi jawabannya 21 Mei 1998." },
    { q: "Urutan presiden Indonesia setelah Soeharto hingga tahun 2014 yang benar adalah ....", options: ["Habibie, Abdurrahman Wahid, Megawati, Susilo Bambang Yudhoyono", "Abdurrahman Wahid, Habibie, Megawati, Susilo Bambang Yudhoyono", "Habibie, Megawati, Abdurrahman Wahid, Susilo Bambang Yudhoyono", "Megawati, Habibie, Abdurrahman Wahid, Susilo Bambang Yudhoyono"], answer: 0, solution: "1. Setelah Soeharto mundur (21 Mei 1998), Wakil Presiden B.J. Habibie naik menjadi presiden. 2. Berikutnya: Abdurrahman Wahid/Gus Dur (1999-2001, dipilih MPR), Megawati Soekarnoputri (2001-2004), dan Susilo Bambang Yudhoyono (2004-2014). 3. Pilihan lain menukar urutan yang benar tersebut. 4. Jadi jawabannya Habibie, Abdurrahman Wahid, Megawati, Susilo Bambang Yudhoyono." },
    { q: "Presiden Indonesia pertama yang dipilih langsung oleh rakyat melalui pemilu adalah ....", options: ["B.J. Habibie", "Abdurrahman Wahid", "Megawati Soekarnoputri", "Susilo Bambang Yudhoyono"], answer: 3, solution: "1. Sebelum 2004, presiden dipilih oleh MPR, bukan langsung oleh rakyat. 2. Pemilu presiden langsung pertama dilaksanakan pada 2004 dan dimenangkan pasangan Susilo Bambang Yudhoyono-Jusuf Kalla. 3. Habibie, Gus Dur, dan Megawati naik menjadi presiden melalui mekanisme MPR. 4. Jadi jawabannya Susilo Bambang Yudhoyono." },
    { q: "Revolusi Industri yang ditandai dengan penggunaan mesin uap bermula di negara ....", options: ["Prancis", "Jerman", "Amerika Serikat", "Inggris"], answer: 3, solution: "1. Revolusi Industri (abad ke-18) ditandai mekanisasi produksi, diawali penyempurnaan mesin uap oleh James Watt (1769). 2. Revolusi ini bermula di Inggris yang kaya batu bara dan memiliki modal dari perdagangan. 3. Prancis, Jerman, dan Amerika Serikat mengalami industrialisasi kemudian menyusul Inggris. 4. Jadi jawabannya Inggris." },
    { q: "Pemicu meletusnya Perang Dunia I adalah ....", options: ["serangan Jerman ke Polandia", "pembunuhan Archduke Franz Ferdinand di Sarajevo", "pengeboman Pearl Harbour", "krisis rudal Kuba"], answer: 1, solution: "1. Perang Dunia I (1914-1918) dipicu oleh peristiwa pada 28 Juni 1914. 2. Putra mahkota Austria-Hongaria, Archduke Franz Ferdinand, dibunuh di Sarajevo oleh Gavrilo Princip sehingga memicu rangkaian deklarasi perang antaraliansi. 3. Serangan ke Polandia memicu PD II, Pearl Harbour menyeret AS ke PD II, dan krisis rudal Kuba terjadi pada 1962. 4. Jadi jawabannya pembunuhan Archduke Franz Ferdinand di Sarajevo." },
    { q: "Bom atom pertama dijatuhkan Sekutu di kota Hiroshima pada tanggal ....", options: ["6 Agustus 1945", "9 Agustus 1945", "15 Agustus 1945", "2 September 1945"], answer: 0, solution: "1. Untuk mempercepat menyerahnya Jepang pada Perang Dunia II, Amerika Serikat menjatuhkan bom atom. 2. Bom pertama dijatuhkan di Hiroshima pada 6 Agustus 1945, disusul bom kedua di Nagasaki pada 9 Agustus 1945. 3. Jepang menyerah pada 15 Agustus 1945 dan upacara penyerahan resmi berlangsung 2 September 1945. 4. Jadi jawabannya 6 Agustus 1945." },
    { q: "Perserikatan Bangsa-Bangsa (PBB) resmi didirikan pada tanggal ....", options: ["26 Juni 1945", "10 Januari 1920", "24 Oktober 1945", "1 Januari 1942"], answer: 2, solution: "1. Setelah Perang Dunia II, negara-negara membentuk organisasi perdamaian dunia pengganti Liga Bangsa-Bangsa. 2. Piagam PBB ditandatangani di San Francisco pada 26 Juni 1945, tetapi PBB resmi berdiri pada 24 Oktober 1945 setelah diratifikasi para anggota pendiri. 3. Tanggal 10 Januari 1920 adalah berdirinya Liga Bangsa-Bangsa dan 1 Januari 1942 adalah Deklarasi PBB. 4. Jadi jawabannya 24 Oktober 1945." },
    { q: "Konferensi Asia-Afrika 1955 di Bandung dilatarbelakangi oleh ....", options: ["agresi militer Belanda ke Yogyakarta", "ketegangan Perang Dingin antara Blok Barat dan Blok Timur", "pemberontakan DI/TII di Jawa Barat", "krisis ekonomi pada masa Orde Baru"], answer: 1, solution: "1. Setelah Perang Dunia II, dunia terpecah menjadi Blok Barat (Amerika Serikat) dan Blok Timur (Uni Soviet) yang bersaing tanpa perang terbuka, disebut Perang Dingin. 2. Negara-negara Asia-Afrika yang baru merdeka khawatir terseret ke dalam konflik kedua blok tersebut. 3. Indonesia memprakarsai KAA 1955 di Bandung sebagai wadah solidaritas sekaligus wujud politik luar negeri bebas aktif. 4. Jadi jawabannya ketegangan Perang Dingin antara Blok Barat dan Blok Timur." },
    { q: "Prasasti Canggal yang berangka tahun 732 M menceritakan Raja Sanjaya ....", options: ["mendirikan lingga Siwa di Gunung Wukir", "membangun Candi Borobudur", "memindahkan ibu kota ke Jawa Timur", "menaklukkan Kerajaan Sriwijaya"], answer: 0, solution: "1. Prasasti Canggal ditemukan di Gunung Wukir, Jawa Tengah, dan berangka tahun 732 M. 2. Isinya menceritakan Raja Sanjaya mendirikan sebuah lingga (lambang Dewa Siwa) sebagai tanda kekuasaannya di Mataram Kuno. 3. Candi Borobudur dibangun wangsa Syailendra yang beragama Buddha, pemindahan ibu kota ke Jawa Timur dilakukan Mpu Sindok, dan Sanjaya tidak pernah menaklukkan Sriwijaya. 4. Jadi jawabannya mendirikan lingga Siwa di Gunung Wukir." },
    { q: "Raja Mataram Kuno yang namanya disebut dalam Prasasti Canggal dan dianggap sebagai pendiri wangsa Sanjaya adalah ....", options: ["Panangkaran", "Pikatan", "Sanjaya", "Balitung"], answer: 2, solution: "1. Prasasti Canggal (732 M) adalah prasasti tertua yang menyebut nama Raja Sanjaya. 2. Sanjaya dianggap pendiri wangsa Sanjaya yang beragama Hindu-Siwa di Mataram Kuno. 3. Panangkaran dan Pikatan adalah raja Mataram Kuno dari generasi sesudah Sanjaya, sedangkan Balitung adalah raja yang membawa Mataram Kuno ke puncak kejayaan. 4. Jadi jawabannya Sanjaya." },
    { q: "Sepeninggal Raja Samaratungga, takhta Mataram Kuno diperebutkan oleh Rakai Pikatan dan ....", options: ["Dapunta Hyang", "Balaputradewa", "Airlangga", "Ken Arok"], answer: 1, solution: "1. Samaratungga adalah raja Mataram Kuno dari wangsa Syailendra yang beragama Buddha. 2. Setelah ia wafat, terjadi perebutan takhta antara Rakai Pikatan (menantu raja, suami Pramodhawardhani) dan Balaputradewa (putra Samaratungga). 3. Rakai Pikatan memenangkan perebutan itu, sedangkan Balaputradewa menyingkir ke Sumatera dan menjadi raja Sriwijaya. 4. Jadi jawabannya Balaputradewa." },
    { q: "Prasasti Nalanda di India menyebutkan bahwa Balaputradewa meminta Raja Dewapaladewa untuk ....", options: ["membangun biara bagi para pendeta Sriwijaya di Nalanda", "menyerang Kerajaan Chola", "mengirim duta ke Tiongkok", "membangun Candi Prambanan"], answer: 0, solution: "1. Setelah kalah dalam perebutan takhta Mataram Kuno, Balaputradewa menjadi raja Sriwijaya di Sumatera. 2. Prasasti Nalanda mencatat ia meminta Raja Dewapaladewa dari Bengala (India) membangun sebuah biara di Nalanda untuk para pendeta asal Sriwijaya. 3. Prasasti ini menjadi bukti hubungan erat Sriwijaya dengan pusat pembelajaran Buddha di India, bukan bukti peperangan atau pembangunan candi di Jawa. 4. Jadi jawabannya membangun biara bagi para pendeta Sriwijaya di Nalanda." },
    { q: "Raja Mataram Kuno yang membawa kerajaannya mencapai puncak kejayaan adalah ....", options: ["Sanjaya", "Balitung", "Wawa", "Daksa"], answer: 1, solution: "1. Setelah masa Rakai Pikatan dan raja-raja sesudahnya, Mataram Kuno mencapai puncak kejayaan pada masa Raja Balitung (898-910 M). 2. Pada masanya wilayah Mataram Kuno meluas dan dikeluarkan banyak prasasti, termasuk Prasasti Mantyasih (907 M) yang memuat daftar silsilah raja-raja Mataram Kuno. 3. Sanjaya adalah pendiri wangsa, sedangkan Wawa dan Daksa adalah raja-raja Mataram Kuno yang berkuasa sesudah Balitung. 4. Jadi jawabannya Balitung." },
    { q: "Tokoh yang memindahkan pusat Kerajaan Mataram Kuno dari Jawa Tengah ke Jawa Timur pada tahun 929 M dan mendirikan wangsa Isyana adalah ....", options: ["Airlangga", "Dharmawangsa", "Ken Arok", "Mpu Sindok"], answer: 3, solution: "1. Sekitar tahun 929 M pusat Kerajaan Mataram Kuno (Medang) dipindahkan dari Jawa Tengah ke Jawa Timur, ke daerah Watugaluh di tepi Sungai Brantas. 2. Tokoh yang memindahkan itu adalah Mpu Sindok, yang kemudian mendirikan wangsa baru bernama wangsa Isyana. 3. Airlangga adalah keturunan Mpu Sindok yang berkuasa kemudian, Dharmawangsa adalah raja Medang sesudahnya, dan Ken Arok adalah pendiri Singasari. 4. Jadi jawabannya Mpu Sindok." },
    { q: "Untuk menghindari perang saudara, Airlangga membagi Kerajaan Kahuripan menjadi dua kerajaan untuk kedua putranya, yaitu ....", options: ["Janggala dan Panjalu", "Singasari dan Kediri", "Medang dan Kahuripan", "Galuh dan Sunda"], answer: 0, solution: "1. Airlangga adalah raja besar Kerajaan Kahuripan di Jawa Timur pada abad ke-11 M. 2. Menjelang akhir pemerintahannya ia membagi kerajaannya menjadi dua, yaitu Janggala dan Panjalu (yang kemudian dikenal sebagai Kediri), masing-masing untuk kedua putranya agar tidak berebut takhta. 3. Singasari dan Kediri adalah kerajaan yang muncul kemudian, sedangkan Medang adalah nama lama Mataram Kuno. 4. Jadi jawabannya Janggala dan Panjalu." },
    { q: "Prasasti Pucangan yang berangka tahun 1041 M (disebut juga Prasasti Kalkuta) berisi kisah tentang ....", options: ["Raja Sanjaya", "Raja Airlangga", "Ken Arok", "Hayam Wuruk"], answer: 1, solution: "1. Prasasti Pucangan dikeluarkan pada tahun 1041 M dan kini tersimpan di Kalkuta, India, sehingga disebut juga Prasasti Kalkuta. 2. Isinya menceritakan riwayat hidup dan perjuangan Raja Airlangga, pendiri Kerajaan Kahuripan. 3. Sanjaya hidup pada abad ke-8, Ken Arok pada abad ke-13, dan Hayam Wuruk pada abad ke-14, sehingga tidak mungkin dikisahkan dalam prasasti tahun 1041 M. 4. Jadi jawabannya Raja Airlangga." },
    { q: "Raja Kediri yang terkenal dengan ramalannya tentang masa depan Nusantara yang disebut Jangka Jayabaya adalah ....", options: ["Kertajaya", "Jayabaya", "Jayawikrama", "Srengga"], answer: 1, solution: "1. Kerajaan Kediri (Panjalu) mencapai kejayaan pada masa Raja Jayabaya yang memerintah sekitar tahun 1135-1157 M. 2. Ia terkenal dengan ramalan-ramalannya tentang masa depan Nusantara yang dihimpun dalam Jangka Jayabaya. 3. Kertajaya adalah raja terakhir Kediri yang dikalahkan Ken Arok, sedangkan nama-nama lain bukan raja Kediri yang terkenal dengan ramalan. 4. Jadi jawabannya Jayabaya." },
    { q: "Perang Ganter pada tahun 1222 menjadi penanda runtuhnya Kerajaan Kediri karena ....", options: ["Ken Arok mengalahkan Kertajaya lalu mendirikan Singasari", "Jayabaya wafat tanpa pewaris", "Kediri diserang pasukan Mongol", "ibu kota Kediri dilanda banjir besar"], answer: 0, solution: "1. Pada akhir masa Kediri, raja terakhirnya adalah Kertajaya yang berselisih dengan kaum brahmana. 2. Ken Arok, akuwu Tumapel, menantang Kertajaya dan mengalahkannya dalam Perang Ganter pada tahun 1222. 3. Kemenangan itu menandai runtuhnya Kediri dan berdirinya Kerajaan Singasari oleh Ken Arok. 4. Jadi jawabannya Ken Arok mengalahkan Kertajaya lalu mendirikan Singasari." },
    { q: "Kerajaan Galuh yang berpusat di daerah Jawa Barat (sekitar Ciamis) memiliki raja yang terkenal bernama ....", options: ["Mulawarman", "Hayam Wuruk", "Sanjaya", "Adityawarman"], answer: 2, solution: "1. Kerajaan Galuh adalah kerajaan Hindu di Jawa Barat yang berpusat di sekitar daerah Ciamis. 2. Raja Galuh yang paling terkenal adalah Sanjaya, yang kemudian juga dikenal sebagai raja Mataram Kuno menurut Prasasti Canggal. 3. Mulawarman adalah raja Kutai, Hayam Wuruk adalah raja Majapahit, dan Adityawarman adalah raja Malayupura. 4. Jadi jawabannya Sanjaya." },
    { q: "Kerajaan Sunda (Pajajaran) beribu kota di Pakuan dan mencapai kejayaan pada masa ....", options: ["Prabu Kertanegara", "Sultan Trenggana", "Sri Baduga Maharaja", "Raden Patah"], answer: 2, solution: "1. Kerajaan Sunda atau Pajajaran adalah kerajaan Hindu di Jawa Barat dengan ibu kota di Pakuan (sekitar Bogor sekarang). 2. Masa kejayaannya terjadi pada masa Sri Baduga Maharaja yang bergelar Prabu Siliwangi (1482-1521), sebagaimana dicatat dalam Prasasti Batutulis. 3. Kertanegara adalah raja Singasari, sedangkan Trenggana dan Raden Patah adalah tokoh Kesultanan Demak. 4. Jadi jawabannya Sri Baduga Maharaja." },
    { q: "Prasasti Talang Tuo yang berangka tahun 684 M berisi ....", options: ["daftar raja-raja Sriwijaya", "kisah perjalanan suci Dapunta Hyang", "doa untuk kesejahteraan rakyat dan pembangunan Taman Sriksetra", "sumpah kesetiaan para panglima"], answer: 2, solution: "1. Prasasti Talang Tuo ditemukan di Palembang dan berangka tahun 684 M, peninggalan Kerajaan Sriwijaya. 2. Isinya berupa doa Dapunta Hyang untuk kesejahteraan seluruh makhluk serta penetapan Taman Sriksetra, taman untuk kemakmuran rakyat. 3. Kisah perjalanan suci Dapunta Hyang terdapat dalam Prasasti Kedukan Bukit, bukan Talang Tuo. 4. Jadi jawabannya doa untuk kesejahteraan rakyat dan pembangunan Taman Sriksetra." },
    { q: "Mahaguru Buddha asal Sriwijaya yang menjadi guru dari Atisha Dipankara adalah ....", options: ["I-Tsing", "Fa-Hsien", "Dharmakirti", "Dharmapala"], answer: 2, solution: "1. Sriwijaya pada abad ke-10-11 M menjadi pusat pembelajaran agama Buddha yang mahagurunya terkenal hingga ke luar Nusantara. 2. Mahaguru itu bernama Dharmakirti (disebut juga Serlingpa Dharmakirti dari Suvarnadvipa), yang menjadi guru dari Atisha Dipankara, biksu asal Bengala yang kemudian menyebarkan Buddha di Tibet. 3. I-Tsing dan Fa-Hsien adalah pendeta Tiongkok yang berkunjung ke Nusantara, bukan guru Atisha. 4. Jadi jawabannya Dharmakirti." },
    { q: "Pada tahun 1025, Sriwijaya mengalami serangan besar dari ....", options: ["pasukan Mongol di bawah Kubilai Khan", "Kerajaan Chola dari India di bawah Rajendra Chola", "Kerajaan Majapahit di bawah Hayam Wuruk", "VOC di bawah Cornelis Speelman"], answer: 1, solution: "1. Pada awal abad ke-11, Kerajaan Chola dari India Selatan di bawah Raja Rajendra Chola memiliki armada laut yang kuat. 2. Pada tahun 1025 armada Chola menyerang dan menjarah ibu kota Sriwijaya, sehingga Sriwijaya sangat lemah setelahnya. 3. Pasukan Mongol menyerang Jawa pada 1293, Majapahit berjaya pada abad ke-14, dan VOC baru datang pada abad ke-17. 4. Jadi jawabannya Kerajaan Chola dari India di bawah Rajendra Chola." },
    { q: "Faktor utama yang menyebabkan kemunduran dan runtuhnya Kerajaan Sriwijaya adalah ....", options: ["letusan Gunung Krakatau", "serangan pasukan Portugis", "perang melawan Kesultanan Demak", "serangan Kerajaan Chola serta desakan kerajaan-kerajaan tetangga"], answer: 3, solution: "1. Sriwijaya yang berjaya sebagai kerajaan maritim mulai melemah sejak serangan armada Chola pada tahun 1025. 2. Setelah itu Sriwijaya terus terdesak oleh kerajaan-kerajaan tetangga yang bangkit, seperti Melayu Dharmasraya dan kemudian Majapahit, hingga akhirnya runtuh sekitar abad ke-14. 3. Letusan Krakatau, Portugis, dan Demak terjadi pada masa atau konteks yang berbeda dan tidak terkait langsung dengan runtuhnya Sriwijaya. 4. Jadi jawabannya serangan Kerajaan Chola serta desakan kerajaan-kerajaan tetangga." },
    { q: "Kerajaan Melayu (Dharmasraya) yang mewarisi pengaruh Sriwijaya di Sumatera berpusat di daerah ....", options: ["Palembang di tepi Sungai Musi", "Jambi di tepi Sungai Batanghari", "Aceh di tepi Sungai Krueng Aceh", "Padang di tepi Sungai Arau"], answer: 1, solution: "1. Setelah Sriwijaya melemah, muncul Kerajaan Melayu dengan pusat di Dharmasraya. 2. Kerajaan ini berpusat di daerah Jambi, tepatnya di tepi Sungai Batanghari, Sumatera. 3. Palembang adalah pusat Sriwijaya, sedangkan Aceh dan Padang bukan pusat Kerajaan Melayu Dharmasraya. 4. Jadi jawabannya Jambi di tepi Sungai Batanghari." },
    { q: "Adityawarman mendirikan Kerajaan Malayupura pada tahun 1347 dengan ibu kota di ....", options: ["Palembang", "Dharmasraya", "Pagaruyung", "Pakuan"], answer: 2, solution: "1. Adityawarman adalah tokoh yang pernah berhubungan dengan Majapahit lalu kembali ke Sumatera. 2. Pada tahun 1347 ia mendirikan Kerajaan Malayupura dengan ibu kota di Pagaruyung, pedalaman Minangkabau, dan ia menganut agama Buddha. 3. Palembang adalah pusat Sriwijaya, Dharmasraya adalah pusat Kerajaan Melayu sebelumnya, dan Pakuan adalah ibu kota Kerajaan Sunda. 4. Jadi jawabannya Pagaruyung." },
    { q: "Pendiri Kerajaan Majapahit pada tahun 1293 yang bergelar Kertarajasa Jayawardhana adalah ....", options: ["Jayanagara", "Wikramawardhana", "Raden Wijaya", "Brawijaya V"], answer: 2, solution: "1. Setelah runtuhnya Singasari akibat serangan Jayakatwang dan pengusiran pasukan Mongol, Raden Wijaya membuka hutan Tarik. 2. Pada tahun 1293 ia mendirikan Kerajaan Majapahit dan naik takhta dengan gelar Kertarajasa Jayawardhana. 3. Jayanagara adalah putra dan penggantinya, sedangkan Wikramawardhana dan Brawijaya V adalah raja-raja Majapahit dari generasi jauh sesudahnya. 4. Jadi jawabannya Raden Wijaya." },
    { q: "Raja kedua Majapahit yang pemerintahannya diwarnai banyak pemberontakan dan wafat pada tahun 1328 adalah ....", options: ["Raden Wijaya", "Tribhuwana", "Hayam Wuruk", "Jayanagara"], answer: 3, solution: "1. Setelah Raden Wijaya wafat, takhta Majapahit diteruskan oleh putranya, Jayanagara. 2. Masa pemerintahannya (1309-1328) diwarnai banyak pemberontakan, antara lain pemberontakan Nambi, Sora, dan Kuti. 3. Jayanagara wafat pada tahun 1328 dan digantikan oleh adiknya, Tribhuwana Tunggadewi. 4. Jadi jawabannya Jayanagara." },
    { q: "Ratu Majapahit yang memerintah tahun 1328-1350 dan mengangkat Gajah Mada menjadi mahapatih adalah ....", options: ["Tribhuwana Tunggadewi", "Dyah Pitaloka", "Ken Dedes", "Gayatri"], answer: 0, solution: "1. Setelah Jayanagara wafat pada 1328, takhta Majapahit dipegang oleh Tribhuwana Tunggadewi. 2. Pada masanya Gajah Mada diangkat menjadi mahapatih (1336) dan mengucapkan Sumpah Palapa. 3. Tribhuwana Tunggadewi adalah ibu dari Hayam Wuruk, sedangkan Dyah Pitaloka adalah putri Sunda dan Ken Dedes adalah permaisuri Ken Arok. 4. Jadi jawabannya Tribhuwana Tunggadewi." },
    { q: "Majapahit mencapai puncak kejayaannya pada masa pemerintahan ....", options: ["Raden Wijaya", "Jayanagara", "Wikramawardhana", "Hayam Wuruk"], answer: 3, solution: "1. Setelah Tribhuwana Tunggadewi turun takhta, Majapahit dipimpin oleh putranya, Hayam Wuruk (1350-1389). 2. Dengan didampingi Mahapatih Gajah Mada, wilayah Majapahit meluas hampir ke seluruh Nusantara sehingga masa ini disebut puncak kejayaan Majapahit. 3. Raden Wijaya adalah pendiri, Jayanagara adalah raja kedua, dan Wikramawardhana berkuasa setelah Hayam Wuruk pada masa kemunduran. 4. Jadi jawabannya Hayam Wuruk." },
    { q: "Perang Bubat pada tahun 1357 terjadi karena ....", options: ["Hayam Wuruk menyerang Kerajaan Sunda", "Sunda menolak membayar upeti", "Gajah Mada menuntut Putri Dyah Pitaloka diserahkan sebagai tanda takluknya Sunda", "perebutan takhta Wikramawardhana dan Bhre Wirabhumi"], answer: 2, solution: "1. Pada tahun 1357 Raja Hayam Wuruk hendak memperistri Dyah Pitaloka, putri Raja Sunda. 2. Rombongan Sunda datang ke Bubat, tetapi Mahapatih Gajah Mada menuntut putri itu diserahkan sebagai tanda takluknya Sunda kepada Majapahit. 3. Tuntutan itu ditolak pihak Sunda sehingga pecah pertempuran yang menewaskan rombongan Sunda, dan Dyah Pitaloka bunuh diri. 4. Jadi jawabannya Gajah Mada menuntut Putri Dyah Pitaloka diserahkan sebagai tanda takluknya Sunda." },
    { q: "Perang Paregreg (1404-1406) yang melemahkan Majapahit adalah perang saudara antara ....", options: ["Hayam Wuruk dan Gajah Mada", "Raden Wijaya dan Jayakatwang", "Wikramawardhana dan Bhre Wirabhumi", "Ken Arok dan Kertajaya"], answer: 2, solution: "1. Setelah Hayam Wuruk wafat, terjadi perebutan takhta Majapahit. 2. Perang Paregreg (1404-1406) adalah perang saudara antara Wikramawardhana (menantu Hayam Wuruk) dan Bhre Wirabhumi (putra Hayam Wuruk dari selir). 3. Perang ini dimenangkan Wikramawardhana tetapi sangat melemahkan Majapahit dan menjadi awal kemundurannya. 4. Jadi jawabannya Wikramawardhana dan Bhre Wirabhumi." },
    { q: "Raja terakhir Kerajaan Majapahit adalah ....", options: ["Hayam Wuruk", "Wikramawardhana", "Girindrawardhana", "Brawijaya V"], answer: 3, solution: "1. Setelah Perang Paregreg, Majapahit terus melemah akibat perebutan kekuasaan dan desakan kerajaan-kerajaan Islam di pesisir. 2. Raja terakhir yang memerintah Majapahit adalah Brawijaya V, setelah itu kekuasaan beralih ke Kesultanan Demak yang didirikan Raden Patah, putranya. 3. Hayam Wuruk adalah raja masa kejayaan, sedangkan Wikramawardhana dan Girindrawardhana berkuasa sebelumnya. 4. Jadi jawabannya Brawijaya V." },
    { q: "Kitab Sutasoma yang memuat semboyan Bhinneka Tunggal Ika dikarang oleh ....", options: ["Mpu Prapanca", "Mpu Kanwa", "Mpu Tantular", "Mpu Sedah"], answer: 2, solution: "1. Kitab Sutasoma adalah karya sastra zaman Majapahit yang memuat kalimat Bhinneka Tunggal Ika tan hana dharma mangrwa. 2. Kitab ini dikarang oleh Mpu Tantular pada masa kejayaan Majapahit. 3. Mpu Prapanca mengarang Negarakertagama, Mpu Kanwa mengarang Arjunawiwaha, dan Mpu Sedah mengarang Bharatayudha. 4. Jadi jawabannya Mpu Tantular." },
    { q: "Kitab Arjunawiwaha yang mengisahkan Arjuna sebagai kiasan Raja Airlangga dikarang oleh ....", options: ["Mpu Tantular", "Mpu Prapanca", "Mpu Panuluh", "Mpu Kanwa"], answer: 3, solution: "1. Kitab Arjunawiwaha menceritakan perkawinan Arjuna dengan bidadari Supraba setelah Arjuna bertapa. 2. Kisah Arjuna dalam kitab ini merupakan kiasan (perlambang) bagi Raja Airlangga dari Kahuripan. 3. Pengarangnya adalah Mpu Kanwa yang hidup pada masa Airlangga, bukan Mpu Tantular, Mpu Prapanca, atau Mpu Panuluh. 4. Jadi jawabannya Mpu Kanwa." },
    { q: "Dalam pemerintahan Majapahit, pejabat yang mengurusi bidang keagamaan disebut ....", options: ["rakryan", "patih", "dharmadyaksa", "tumenggung"], answer: 2, solution: "1. Pemerintahan Majapahit memiliki pembagian tugas yang teratur di bawah raja. 2. Urusan keagamaan, baik agama Siwa maupun Buddha, diawasi oleh pejabat yang disebut dharmadyaksa. 3. Rakryan adalah gelar para menteri dan pembesar, patih adalah perdana menteri, dan tumenggung adalah pejabat keamanan. 4. Jadi jawabannya dharmadyaksa." },
    { q: "Dewan menteri utama yang membantu raja dalam pemerintahan Majapahit disebut ....", options: ["dharmadyaksa", "bhre", "demang", "rakryan mahamantri katrini"], answer: 3, solution: "1. Raja Majapahit dibantu oleh para pejabat tinggi dalam menjalankan pemerintahan. 2. Dewan menteri utama yang menjadi pembantu terdekat raja disebut rakryan mahamantri katrini, yang terdiri atas tiga orang mahamantri. 3. Dharmadyaksa mengurusi agama, bhre adalah gelar penguasa daerah, dan demang adalah pejabat setingkat di bawahnya. 4. Jadi jawabannya rakryan mahamantri katrini." },
    { q: "Candi Penataran di Blitar dikenal sebagai ....", options: ["candi Buddha terbesar di dunia", "candi Hindu terbesar di Jawa Timur", "candi peninggalan Sriwijaya", "candi Islam tertua di Jawa"], answer: 1, solution: "1. Candi Penataran (Candi Palah) terletak di Blitar, Jawa Timur, dan pembangunannya berlangsung sejak masa Kediri hingga disempurnakan pada masa Majapahit. 2. Candi ini dikenal sebagai candi Hindu terbesar dan termegah di Jawa Timur. 3. Candi Buddha terbesar di dunia adalah Borobudur, sedangkan Sriwijaya berpusat di Sumatera dan tidak meninggalkan candi Islam. 4. Jadi jawabannya candi Hindu terbesar di Jawa Timur." },
    { q: "Corak keberagamaan masyarakat Jawa pada masa Hindu-Buddha yang memadukan pemujaan Siwa dan Buddha disebut ....", options: ["sinkretisme Hindu-Islam", "animisme murni", "monoteisme", "sinkretisme Siwa-Buddha"], answer: 3, solution: "1. Pada masa kerajaan Hindu-Buddha di Jawa, agama Siwa dan agama Buddha berkembang berdampingan dan saling memengaruhi. 2. Para raja dan masyarakat memadukan kedua ajaran itu, misalnya raja dianggap titisan Siwa sekaligus Buddha, sehingga coraknya disebut sinkretisme Siwa-Buddha. 3. Sinkretisme Hindu-Islam muncul jauh kemudian, sedangkan animisme dan monoteisme tidak menggambarkan perpaduan Siwa-Buddha. 4. Jadi jawabannya sinkretisme Siwa-Buddha." },
    { q: "Komoditas utama yang diperdagangkan kerajaan-kerajaan Hindu-Buddha dalam perdagangan internasional adalah ....", options: ["mesin dan kendaraan", "kain sutra Eropa", "rempah-rempah", "senjata api"], answer: 2, solution: "1. Kerajaan-kerajaan Hindu-Buddha seperti Sriwijaya terletak di jalur pelayaran antara India dan Tiongkok. 2. Komoditas utama yang diperdagangkan dari Nusantara adalah rempah-rempah (lada, cengkeh, pala) yang sangat dicari pedagang asing. 3. Mesin, kendaraan, dan senjata api adalah barang masa modern, sedangkan kain sutra Eropa bukan komoditas ekspor Nusantara. 4. Jadi jawabannya rempah-rempah." },
    { q: "Teori yang menyatakan agama Hindu-Buddha dibawa ke Nusantara oleh kaum brahmana yang diundang para penguasa lokal disebut teori ....", options: ["Ksatria", "Waisya", "Brahmana", "Arus Balik"], answer: 2, solution: "1. Salah satu teori masuknya Hindu-Buddha menyatakan penyebarnya adalah kaum brahmana dari India. 2. Para brahmana ini diundang oleh penguasa lokal untuk menjadi penasihat spiritual dan memimpin upacara keagamaan, sehingga pengaruh Hindu-Buddha masuk melalui jalur keagamaan. 3. Teori ini dikenal sebagai teori Brahmana yang dikemukakan oleh J.C. van Leur. 4. Jadi jawabannya Brahmana." },
    { q: "Teori yang menyatakan Hindu-Buddha disebarkan oleh kaum prajurit (ksatria) yang melarikan diri atau menaklukkan wilayah Nusantara disebut teori ....", options: ["Brahmana", "Ksatria", "Waisya", "Arus Balik"], answer: 1, solution: "1. Teori ini berpendapat kaum ksatria (prajurit) dari India datang ke Nusantara karena kalah perang atau melarikan diri, lalu mendirikan koloni dan kerajaan. 2. Melalui kekuasaan politik itulah budaya dan agama Hindu-Buddha disebarkan. 3. Teori ini dikenal sebagai teori Ksatria yang dikemukakan antara lain oleh C.C. Berg. 4. Jadi jawabannya Ksatria." },
    { q: "Teori yang menyatakan Hindu-Buddha dibawa oleh para pedagang yang berlayar dan berdagang ke Nusantara disebut teori ....", options: ["Brahmana", "Ksatria", "Arus Balik", "Waisya"], answer: 3, solution: "1. Jalur perdagangan antara India dan Nusantara sudah ramai sejak awal Masehi. 2. Teori ini menyatakan para pedagang (kaum waisya) dari India yang singgah dan menetap di Nusantara turut menyebarkan agama Hindu-Buddha melalui kontak dagang. 3. Teori ini dikenal sebagai teori Waisya yang dikemukakan oleh N.J. Krom. 4. Jadi jawabannya Waisya." },
    { q: "Teori arus balik yang dikemukakan F.D.K. Bosch menekankan bahwa ....", options: ["bangsa Indonesia berperan aktif mempelajari Hindu-Buddha ke India lalu menyebarkannya kembali", "kaum brahmana India diundang ke Nusantara", "kaum ksatria menaklukkan Nusantara", "para pedagang menyebarkan agama lewat jalur dagang"], answer: 0, solution: "1. Berbeda dengan teori-teori sebelumnya yang menekankan peran orang India, teori arus balik menekankan peran aktif bangsa Indonesia sendiri. 2. Menurut F.D.K. Bosch, para pemuda Indonesia berlayar ke India untuk mempelajari agama dan kebudayaan Hindu-Buddha, lalu kembali ke Nusantara dan menyebarkannya. 3. Karena ada arus pergi dan arus kembali inilah teori ini disebut teori arus balik. 4. Jadi jawabannya bangsa Indonesia berperan aktif mempelajari Hindu-Buddha ke India lalu menyebarkannya kembali." },
    { q: "Prasasti Canggal ditulis dengan huruf .... dan berbahasa ....", options: ["Jawa Kuno dan Melayu Kuno", "Pallawa dan Sanskerta", "Arab dan Melayu", "Latin dan Belanda"], answer: 1, solution: "1. Prasasti-prasasti tertua di Nusantara umumnya menggunakan huruf dan bahasa yang berasal dari India. 2. Prasasti Canggal (732 M) ditulis dengan huruf Pallawa dan berbahasa Sanskerta, sama seperti Prasasti Yupa di Kutai. 3. Huruf Jawa Kuno muncul pada prasasti yang lebih muda, sedangkan huruf Arab dan Latin baru dipakai pada masa Islam dan kolonial. 4. Jadi jawabannya Pallawa dan Sanskerta." },
    { q: "Pendeta Tiongkok yang belajar agama Buddha di Sriwijaya pada abad ke-7 dan mencatatnya sebagai pusat pembelajaran Buddha adalah ....", options: ["Fa-Hsien", "Hiuen Tsang", "Atisha", "I-Tsing"], answer: 3, solution: "1. Pada abad ke-7, Sriwijaya sudah dikenal sebagai pusat pembelajaran agama Buddha di Asia Tenggara. 2. Pendeta Tiongkok bernama I-Tsing singgah dan belajar di Sriwijaya dalam perjalanannya ke India, lalu mencatat bahwa Sriwijaya adalah tempat yang tepat untuk mempelajari agama Buddha. 3. Fa-Hsien dan Hiuen Tsang adalah pendeta Tiongkok dari masa berbeda, sedangkan Atisha adalah biksu Bengala yang belajar pada Dharmakirti di Sriwijaya. 4. Jadi jawabannya I-Tsing." },
    { q: "Sultan Aceh Darussalam yang membawa kerajaan mencapai puncak kejayaan pada tahun 1607-1636 adalah ....", options: ["Sultan Malikussaleh", "Sultan Iskandar Thani", "Sultan Iskandar Muda", "Sultan Alaiddin Riayat Syah"], answer: 2, solution: "1. Kesultanan Aceh Darussalam mencapai puncak kejayaan pada awal abad ke-17. 2. Sultan Iskandar Muda memerintah tahun 1607-1636, memperluas wilayah, memperkuat armada laut, dan menjadikan Aceh bandar perdagangan lada yang ramai. 3. Malikussaleh adalah pendiri Samudra Pasai dan Iskandar Thani adalah pengganti Iskandar Muda, bukan pembawa puncak kejayaan. 4. Jadi jawabannya Sultan Iskandar Muda." },
    { q: "Laksamana perempuan Kesultanan Aceh yang memimpin pasukan Inong Balee adalah ....", options: ["Cut Nyak Dien", "Laksamana Malahayati", "Cut Meutia", "Ratu Safiatuddin"], answer: 1, solution: "1. Kesultanan Aceh memiliki laksamana perempuan bernama Keumalahayati (Malahayati). 2. Ia memimpin pasukan Inong Balee yang beranggotakan para janda prajurit Aceh yang gugur melawan Portugis. 3. Cut Nyak Dien dan Cut Meutia adalah pahlawan perempuan masa Perang Aceh abad ke-19, sedangkan Ratu Safiatuddin adalah ratu Aceh pengganti Iskandar Thani. 4. Jadi jawabannya Laksamana Malahayati." },
    { q: "Komoditas utama yang diperdagangkan Kesultanan Aceh Darussalam hingga menjadi bandar ramai pada abad ke-17 adalah ....", options: ["lada", "cengkih", "pala", "kayu cendana"], answer: 0, solution: "1. Letak Aceh yang strategis di ujung barat jalur perdagangan Selat Malaka membuatnya menjadi bandar yang ramai. 2. Komoditas utama yang diperdagangkan Aceh adalah lada yang diburu para pedagang Eropa dan Asia. 3. Cengkih dan pala adalah komoditas utama Maluku, bukan Aceh. 4. Jadi jawabannya lada." },
    { q: "Campur tangan VOC dalam konflik Sultan Ageng Tirtayasa dan putranya, Sultan Haji, ditunjukkan oleh peristiwa ....", options: ["membantu Sultan Ageng menyerang Batavia", "menjadi penengah yang netral di antara keduanya", "memboikot perdagangan lada Banten", "mendukung Sultan Haji untuk merebut takhta ayahnya"], answer: 3, solution: "1. Sultan Ageng Tirtayasa menentang monopoli VOC, sedangkan putranya Sultan Haji berselisih paham dengannya. 2. Sultan Haji meminta bantuan VOC untuk merebut takhta ayahnya, sehingga VOC ikut campur dalam urusan dalam negeri Banten. 3. Akibatnya Sultan Ageng disingkirkan dan Banten jatuh ke dalam pengaruh VOC. 4. Jadi jawabannya mendukung Sultan Haji untuk merebut takhta ayahnya." },
    { q: "Pada masa kejayaannya abad ke-17, Kesultanan Banten dikenal sebagai ....", options: ["pusat penyebaran agama Hindu di Jawa Barat", "pusat perdagangan lada dan bandar internasional yang ramai", "kerajaan agraris penghasil beras terbesar", "markas utama armada Portugis"], answer: 1, solution: "1. Pada abad ke-17 Kesultanan Banten di bawah Sultan Ageng Tirtayasa mencapai masa kejayaan. 2. Pelabuhan Banten menjadi bandar internasional yang ramai disinggahi pedagang Eropa dan Asia untuk membeli lada. 3. Banten bukan pusat Hindu dan bukan markas Portugis. 4. Jadi jawabannya pusat perdagangan lada dan bandar internasional yang ramai." },
    { q: "Persaingan Kesultanan Ternate dan Tidore dalam perdagangan rempah diperkuat oleh dukungan bangsa Eropa, yaitu ....", options: ["Ternate didukung Spanyol dan Tidore didukung Portugis", "keduanya didukung VOC", "Ternate didukung Portugis dan Tidore didukung Spanyol", "keduanya didukung Inggris"], answer: 2, solution: "1. Ternate dan Tidore adalah dua kesultanan di Maluku yang bersaing memperebutkan perdagangan rempah cengkih dan pala. 2. Persaingan itu diperkuat dukungan bangsa Eropa: Ternate bersekutu dengan Portugis, sedangkan Tidore bersekutu dengan Spanyol. 3. VOC baru berperan dominan kemudian setelah Portugis dan Spanyol melemah. 4. Jadi jawabannya Ternate didukung Portugis dan Tidore didukung Spanyol." },
    { q: "Sultan Tidore yang memimpin perlawanan besar-besaran terhadap VOC pada akhir abad ke-18 dengan dukungan Inggris adalah ....", options: ["Sultan Baabullah", "Sultan Hairun", "Sultan Zainal Abidin", "Sultan Nuku"], answer: 3, solution: "1. Pada akhir abad ke-18 muncul perlawanan besar terhadap VOC di Maluku. 2. Sultan Nuku (Nuku Muhammad Amiruddin) dari Tidore memimpin perlawanan anti-VOC sekitar tahun 1780-1805 dengan dukungan Inggris. 3. Sultan Baabullah adalah sultan Ternate abad ke-16 yang mengusir Portugis, bukan melawan VOC abad ke-18. 4. Jadi jawabannya Sultan Nuku." },
    { q: "Mangkubumi Kesultanan Gowa yang terkenal sebagai cendekiawan, menguasai banyak bahasa asing dan ilmu pengetahuan, adalah ....", options: ["Sultan Hasanuddin", "Karaeng Pattingalloang", "Arung Palakka", "Karaeng Matoaya"], answer: 1, solution: "1. Karaeng Pattingalloang adalah mangkubumi (perdana menteri) Kesultanan Gowa pada masa Sultan Hasanuddin. 2. Ia terkenal sebagai cendekiawan yang menguasai banyak bahasa asing dan ilmu pengetahuan, serta menjadi penasihat utama sultan. 3. Sultan Hasanuddin adalah rajanya, Arung Palakka adalah sekutu VOC dari Bone, dan Karaeng Matoaya adalah raja Tallo. 4. Jadi jawabannya Karaeng Pattingalloang." },
    { q: "Isi pokok Perjanjian Bongaya (1667) yang merugikan Kesultanan Gowa adalah ....", options: ["Gowa wajib mengakui monopoli dagang VOC dan menghancurkan benteng-bentengnya", "Gowa boleh berdagang bebas dengan semua bangsa Eropa", "VOC mengakui kedaulatan penuh Gowa atas Sulawesi", "Gowa dan VOC berbagi wilayah Maluku secara merata"], answer: 0, solution: "1. Perjanjian Bongaya ditandatangani tahun 1667 setelah Gowa kalah perang melawan VOC. 2. Isi pokoknya sangat merugikan Gowa: mengakui monopoli dagang VOC, menghancurkan benteng-benteng pertahanan, dan membayar biaya perang. 3. Pilihan lain bertentangan dengan isi perjanjian yang justru melemahkan Gowa. 4. Jadi jawabannya Gowa wajib mengakui monopoli dagang VOC dan menghancurkan benteng-bentengnya." },
    { q: "Raja Tallo yang pertama kali memeluk Islam pada tahun 1605 dengan gelar Sultan Abdullah Awwalul Islam adalah ....", options: ["Sultan Hasanuddin", "Karaeng Pattingalloang", "I Mangarangi Daeng Manrabbia", "Arung Palakka"], answer: 2, solution: "1. Islam masuk ke Sulawesi Selatan pada awal abad ke-17. 2. Raja Tallo, I Mangarangi Daeng Manrabbia, memeluk Islam pada tahun 1605 dan bergelar Sultan Abdullah Awwalul Islam (sultan yang pertama masuk Islam). 3. Setelah raja masuk Islam, rakyat Gowa-Tallo pun berbondong-bondong memeluk Islam. 4. Jadi jawabannya I Mangarangi Daeng Manrabbia." },
    { q: "Pendiri Kesultanan Banjar yang masuk Islam dengan bantuan Kesultanan Demak dan bergelar Sultan Suriansyah adalah ....", options: ["Pangeran Tumenggung", "Pangeran Antasari", "Sultan Adam", "Pangeran Samudra"], answer: 3, solution: "1. Kesultanan Banjar di Kalimantan Selatan berdiri pada abad ke-16. 2. Pendirinya adalah Pangeran Samudra yang masuk Islam dengan bantuan Kesultanan Demak, lalu bergelar Sultan Suriansyah. 3. Pangeran Tumenggung adalah lawannya yang kalah, sedangkan Pangeran Antasari adalah pahlawan Perang Banjar abad ke-19. 4. Jadi jawabannya Pangeran Samudra." },
    { q: "Raja Kerajaan Pajang yang bernama asli Joko Tingkir adalah ....", options: ["Sultan Trenggana", "Sultan Hadiwijaya", "Arya Penangsang", "Sunan Prawoto"], answer: 1, solution: "1. Setelah Demak runtuh, pusat kekuasaan Islam di Jawa pindah ke Pajang. 2. Raja Pajang adalah Joko Tingkir yang bergelar Sultan Hadiwijaya. 3. Sultan Trenggana adalah raja Demak dan Arya Penangsang adalah adipati Jipang yang dikalahkannya. 4. Jadi jawabannya Sultan Hadiwijaya." },
    { q: "Pada masa pemerintahan Amangkurat I, Mataram Islam diguncang pemberontakan besar yang dipimpin oleh ....", options: ["Trunajaya", "Untung Suropati", "Diponegoro", "Raden Mas Said"], answer: 0, solution: "1. Amangkurat I memerintah Mataram Islam tahun 1646-1677 dengan pemerintahan yang keras. 2. Pada masanya meletus pemberontakan besar Trunajaya (1674) yang dibantu VOC dan nyaris meruntuhkan Mataram. 3. Untung Suropati dan Diponegoro adalah tokoh perlawanan pada masa yang berbeda. 4. Jadi jawabannya Trunajaya." },
    { q: "Perjanjian Giyanti tahun 1755 membagi Mataram Islam menjadi dua kerajaan, yaitu ....", options: ["Banten dan Cirebon", "Gowa dan Tallo", "Surakarta dan Yogyakarta", "Demak dan Pajang"], answer: 2, solution: "1. Perpecahan Mataram Islam terjadi melalui Perjanjian Giyanti tahun 1755 yang dimediasi VOC. 2. Mataram dibagi dua: Kasunanan Surakarta untuk Pakubuwono III dan Kasultanan Yogyakarta untuk Hamengkubuwono I. 3. Pembagian lain seperti Banten-Cirebon atau Gowa-Tallo tidak terkait perjanjian ini. 4. Jadi jawabannya Surakarta dan Yogyakarta." },
    { q: "Perjanjian Salatiga tahun 1757 melahirkan Kadipaten Mangkunegaran yang diberikan kepada ....", options: ["Hamengkubuwono I", "Pakubuwono III", "Amangkurat III", "Raden Mas Said"], answer: 3, solution: "1. Setelah Giyanti, Raden Mas Said yang belum puas terus bergerilya melawan VOC. 2. Melalui Perjanjian Salatiga tahun 1757, ia diakui sebagai Adipati Mangkunegara I dengan wilayah Kadipaten Mangkunegaran di Surakarta. 3. Hamengkubuwono I adalah raja Yogyakarta dan Pakubuwono III adalah raja Surakarta hasil Giyanti. 4. Jadi jawabannya Raden Mas Said." },
    { q: "Raja Mataram yang memindahkan pusat keraton dari Kartasura ke Surakarta pada tahun 1745 adalah ....", options: ["Amangkurat I", "Pakubuwono II", "Pakubuwono I", "Amangkurat II"], answer: 1, solution: "1. Pusat pemerintahan Mataram beberapa kali berpindah: Kotagede, Karta, Plered, hingga Kartasura. 2. Pakubuwono II memindahkan keraton dari Kartasura ke Surakarta pada tahun 1745. 3. Amangkurat I memindahkan pusat ke Plered, bukan ke Surakarta. 4. Jadi jawabannya Pakubuwono II." },
    { q: "Pendiri Kesultanan Cirebon yang bernama asli Syarif Hidayatullah adalah ....", options: ["Sunan Gunung Jati", "Sunan Ampel", "Sunan Kalijaga", "Sunan Kudus"], answer: 0, solution: "1. Kesultanan Cirebon di Jawa Barat didirikan pada awal abad ke-16. 2. Pendirinya adalah Syarif Hidayatullah yang dikenal sebagai Sunan Gunung Jati, salah satu Wali Songo. 3. Sunan Ampel, Kalijaga, dan Kudus menyebarkan Islam di daerah Jawa Tengah dan Timur. 4. Jadi jawabannya Sunan Gunung Jati." },
    { q: "Runtuhnya Kesultanan Demak ditandai dengan kemenangan Joko Tingkir atas ....", options: ["Sultan Trenggana", "Fatahillah", "Arya Penangsang", "Raden Patah"], answer: 2, solution: "1. Setelah Sultan Trenggana wafat (1546), Demak dilanda perebutan kekuasaan. 2. Arya Penangsang, Adipati Jipang, membunuh para pewaris takhta Demak. 3. Joko Tingkir (Sultan Hadiwijaya) kemudian mengalahkan Arya Penangsang tahun 1549, menandai runtuhnya Demak dan berdirinya Pajang. 4. Jadi jawabannya Arya Penangsang." },
    { q: "Masjid Agung Demak yang menjadi simbol kejayaan Islam di Jawa dibangun pada masa pemerintahan ....", options: ["Sultan Agung", "Amangkurat I", "Pakubuwono II", "Raden Patah"], answer: 3, solution: "1. Masjid Agung Demak adalah masjid kuno peninggalan Kesultanan Demak. 2. Masjid ini dibangun pada masa pemerintahan Raden Patah dengan bantuan para Wali Songo, dan beratap tumpang khas akulturasi Jawa-Islam. 3. Sultan Agung dan Amangkurat I adalah raja Mataram yang berkuasa jauh sesudah Demak runtuh. 4. Jadi jawabannya Raden Patah." },
    { q: "Teori yang menyatakan Islam masuk ke Nusantara dibawa oleh para pedagang dari Gujarat, India, dikemukakan oleh ....", options: ["Hamka", "Snouck Hurgronje", "Husein Djajadiningrat", "Slamet Muljana"], answer: 1, solution: "1. Salah satu teori masuknya Islam ke Nusantara adalah teori Gujarat. 2. Teori ini dikemukakan Snouck Hurgronje: Islam dibawa para pedagang dari Gujarat, India, pada abad ke-13, dengan bukti batu nisan dan kesamaan mazhab Syafi'i. 3. Hamka mengemukakan teori Mekkah dan Husein Djajadiningrat mengemukakan teori Persia. 4. Jadi jawabannya Snouck Hurgronje." },
    { q: "Teori yang menyatakan Islam masuk ke Nusantara langsung dari Arab (Mekkah) sejak abad ke-7 M dikemukakan oleh ....", options: ["Hamka", "Snouck Hurgronje", "Van Leur", "Pijnappel"], answer: 0, solution: "1. Teori Mekkah menyatakan Islam masuk ke Nusantara langsung dari Arab sejak abad ke-7 M. 2. Teori ini dikemukakan oleh Hamka (Haji Abdul Malik Karim Amrullah). 3. Snouck Hurgronje mengemukakan teori Gujarat dan Pijnappel mendukung teori Gujarat pula. 4. Jadi jawabannya Hamka." },
    { q: "Saluran utama penyebaran Islam di Nusantara pada awalnya adalah melalui ....", options: ["penaklukan militer", "paksaan penguasa kolonial", "perdagangan oleh para pedagang Muslim", "migrasi besar-besaran"], answer: 2, solution: "1. Islam pertama kali menyebar di pesisir Nusantara melalui para pedagang Muslim dari Gujarat, Arab, dan Persia. 2. Melalui aktivitas dagang yang damai, para pedagang memperkenalkan ajaran Islam kepada penduduk setempat. 3. Tidak ada penaklukan militer besar dalam penyebaran Islam di Nusantara. 4. Jadi jawabannya perdagangan oleh para pedagang Muslim." },
    { q: "Penyebaran Islam melalui saluran perkawinan terjadi ketika ....", options: ["raja memaksa rakyatnya menikah", "VOC mengatur pernikahan campuran", "para wali melarang pernikahan campuran", "pedagang Muslim menikahi putri bangsawan setempat"], answer: 3, solution: "1. Salah satu saluran Islamisasi adalah melalui perkawinan. 2. Para pedagang Muslim yang menetap menikahi putri bangsawan atau saudagar setempat, lalu anak keturunannya menjadi penyebar Islam. 3. Pilihan lain tidak mencerminkan proses perkawinan sebagai saluran dakwah. 4. Jadi jawabannya pedagang Muslim menikahi putri bangsawan setempat." },
    { q: "Sunan Ampel mendirikan pesantren di Ampeldenta, Surabaya, sebagai pusat ....", options: ["perdagangan rempah", "pendidikan dan dakwah Islam", "latihan militer", "pemerintahan kerajaan"], answer: 1, solution: "1. Sunan Ampel mendirikan pesantren di Ampeldenta, Surabaya, pada abad ke-15. 2. Pesantren menjadi pusat pendidikan sekaligus dakwah Islam: para santri belajar agama lalu menyebarkannya ke daerah asal mereka. 3. Sunan Ampel juga mengajarkan falsafah Moh Limo, yaitu larangan berjudi, minum minuman keras, mencuri, berzina, dan mengonsumsi candu. 4. Jadi jawabannya pendidikan dan dakwah Islam." },
    { q: "Penyebaran Islam melalui saluran politik ditunjukkan oleh peristiwa ....", options: ["raja yang masuk Islam kemudian diikuti oleh rakyatnya", "VOC memaksa raja memeluk Islam", "para pedagang mendirikan partai politik", "wali songo menjadi gubernur VOC"], answer: 0, solution: "1. Islam juga menyebar melalui saluran politik kekuasaan. 2. Ketika seorang raja memeluk Islam, para bangsawan dan rakyatnya cenderung mengikuti, sehingga Islam cepat berkembang di wilayah kerajaan. 3. Contohnya Raja Tallo (1605) dan Pangeran Samudra dari Banjar yang masuk Islam lalu diikuti rakyatnya. 4. Jadi jawabannya raja yang masuk Islam kemudian diikuti oleh rakyatnya." },
    { q: "Bukti arkeologis tertua masuknya Islam di Jawa adalah makam ....", options: ["Malik Ibrahim di Demak (1419 M)", "Sunan Ampel di Surabaya (1400 M)", "Fatimah binti Maimun di Leran, Gresik (1082 M)", "Sunan Giri di Malaka (1300 M)"], answer: 2, solution: "1. Bukti arkeologis tertua Islam di Jawa adalah makam Fatimah binti Maimun di Leran, Gresik. 2. Batu nisannya berangka tahun 1082 M (475 H), menunjukkan Islam sudah ada di Jawa sejak abad ke-11. 3. Makam Malik Ibrahim (1419 M) lebih muda, sedangkan pilihan lain bukan bukti arkeologis tertua. 4. Jadi jawabannya Fatimah binti Maimun di Leran, Gresik (1082 M)." },
    { q: "Makam Maulana Malik Ibrahim (Sunan Gresik) yang wafat pada tahun 1419 M terletak di ....", options: ["Demak", "Gresik", "Tuban", "Cirebon"], answer: 1, solution: "1. Maulana Malik Ibrahim dikenal sebagai Sunan Gresik dan wali tertua di antara Wali Songo. 2. Makamnya terletak di Gresik, Jawa Timur, dengan angka tahun wafat 1419 M. 3. Makam ini menjadi bukti kuat perkembangan Islam di pesisir Jawa awal abad ke-15. 4. Jadi jawabannya Gresik." },
    { q: "Bentuk atap tumpang pada masjid-masjid kuno seperti Masjid Agung Demak menunjukkan ....", options: ["pengaruh arsitektur Eropa", "peniruan masjid di Timur Tengah", "gaya bangunan kolonial Belanda", "akulturasi budaya Hindu-Jawa dengan Islam"], answer: 3, solution: "1. Masjid-masjid kuno peninggalan kerajaan Islam seperti Masjid Agung Demak beratap tumpang (bersusun). 2. Bentuk atap tumpang berasal dari arsitektur Jawa-Hindu yang dipadukan dengan fungsi masjid, sehingga menjadi bukti akulturasi budaya Hindu-Jawa dengan Islam. 3. Bukan pengaruh Eropa maupun peniruan masjid Timur Tengah yang umumnya berkubah. 4. Jadi jawabannya akulturasi budaya Hindu-Jawa dengan Islam." },
    { q: "Sultan Agung mengganti sistem penanggalan Saka menjadi kalender Jawa yang bercorak Islam pada tahun ....", options: ["1633", "1527", "1619", "1755"], answer: 0, solution: "1. Sultan Agung, raja terbesar Mataram Islam, melakukan akulturasi budaya dalam sistem penanggalan. 2. Pada tahun 1633 ia mengganti kalender Saka (Hindu) menjadi kalender Jawa yang memadukan perhitungan Islam dan Jawa. 3. Tahun 1527 adalah perebutan Sunda Kelapa dan 1755 adalah Perjanjian Giyanti. 4. Jadi jawabannya 1633." },
    { q: "Sunan Giri menyebarkan Islam melalui jalur pendidikan dengan mendirikan pesantren di ....", options: ["Ampeldenta, Surabaya", "Kudus", "Giri, Gresik", "Banten"], answer: 2, solution: "1. Sunan Giri (Raden Paku) memilih jalur pendidikan dalam berdakwah. 2. Ia mendirikan pesantren di Bukit Giri, Gresik, yang murid-muridnya kemudian menyebarkan Islam ke berbagai daerah. 3. Pesantren Ampeldenta didirikan Sunan Ampel, bukan Sunan Giri. 4. Jadi jawabannya Giri, Gresik." },
    { q: "Sunan Bonang berdakwah dengan menggunakan media kesenian berupa ....", options: ["wayang kulit", "gamelan dan tembang suluk", "tari topeng", "ukiran kaligrafi"], answer: 1, solution: "1. Sunan Bonang berdakwah di daerah Tuban dengan pendekatan kesenian. 2. Ia menggunakan gamelan dan tembang-tembang suluk (di antaranya Suluk Wujil) yang berisi ajaran tasawuf agar mudah diterima masyarakat. 3. Wayang kulit adalah media dakwah Sunan Kalijaga. 4. Jadi jawabannya gamelan dan tembang suluk." },
    { q: "Ciri khas dakwah Sunan Drajat adalah menekankan ....", options: ["kesejahteraan sosial dan etos kerja", "perlawanan bersenjata", "perdagangan internasional", "pembangunan istana"], answer: 0, solution: "1. Sunan Drajat berdakwah di daerah Sedayu, Lamongan. 2. Dakwahnya menekankan kesejahteraan sosial dan etos kerja, dirumuskan dalam ajaran Catur Piwulang. 3. Ia tidak menggunakan perlawanan bersenjata dalam menyebarkan Islam. 4. Jadi jawabannya kesejahteraan sosial dan etos kerja." },
    { q: "Sunan Kalijaga terkenal menggunakan media dakwah berupa ....", options: ["kitab kuning", "meriam", "kapal dagang", "wayang kulit"], answer: 3, solution: "1. Sunan Kalijaga (Raden Said) adalah wali yang paling luwes dalam berdakwah. 2. Ia menggunakan wayang kulit sebagai media dakwah dengan menyisipkan ajaran Islam ke dalam cerita pewayangan. 3. Kitab, meriam, dan kapal dagang bukan media dakwahnya. 4. Jadi jawabannya wayang kulit." },
    { q: "Sebagai bentuk toleransi kepada masyarakat Hindu, Sunan Kudus ....", options: ["membangun candi Hindu", "melarang salat berjamaah", "melarang penyembelihan sapi di Kudus", "menutup Masjid Menara Kudus"], answer: 2, solution: "1. Sunan Kudus berdakwah di Kudus yang masyarakatnya masih kuat memegang tradisi Hindu. 2. Sebagai bentuk toleransi, ia melarang para pengikutnya menyembelih sapi karena sapi dihormati umat Hindu, dan membangun Masjid Menara Kudus yang menaranya menyerupai candi. 3. Ia tidak melarang salat berjamaah maupun menutup masjid. 4. Jadi jawabannya melarang penyembelihan sapi di Kudus." },
    { q: "Sunan Muria yang berdakwah di daerah pedalaman Gunung Muria adalah putra dari ....", options: ["Sunan Ampel", "Sunan Kalijaga", "Sunan Giri", "Maulana Malik Ibrahim"], answer: 1, solution: "1. Sunan Muria berdakwah di daerah terpencil sekitar Gunung Muria dengan cara yang sederhana dan merakyat. 2. Ia adalah putra Sunan Kalijaga, sehingga melanjutkan pendekatan dakwah yang luwes seperti ayahnya. 3. Sunan Ampel dan Sunan Giri adalah wali lain yang tidak memiliki hubungan ayah-anak dengannya. 4. Jadi jawabannya Sunan Kalijaga." },
    { q: "Hamzah Fansuri dikenal sebagai tokoh ....", options: ["tasawuf (sufi) dan sastra Melayu di Aceh", "panglima perang Demak", "pendiri Kesultanan Banten", "penyusun kitab undang-undang"], answer: 0, solution: "1. Hamzah Fansuri hidup di Aceh pada abad ke-16 hingga awal abad ke-17. 2. Ia dikenal sebagai tokoh tasawuf (sufi) sekaligus pelopor sastra Melayu melalui syair-syairnya. 3. Ia bukan panglima perang maupun pendiri kesultanan. 4. Jadi jawabannya tasawuf (sufi) dan sastra Melayu di Aceh." },
    { q: "Kesultanan Pontianak di Kalimantan Barat didirikan pada tahun 1771 oleh ....", options: ["Sultan Suriansyah", "Pangeran Antasari", "Sultan Adam", "Syarif Abdurrahman Alkadrie"], answer: 3, solution: "1. Kesultanan Pontianak di Kalimantan Barat didirikan pada tahun 1771. 2. Pendirinya adalah Syarif Abdurrahman Alkadrie, seorang keturunan Arab yang membuka pemukiman di muara Sungai Kapuas. 3. Sultan Suriansyah adalah pendiri Kesultanan Banjar dan Pangeran Antasari adalah pahlawan Perang Banjar. 4. Jadi jawabannya Syarif Abdurrahman Alkadrie." },
    { q: "Kesultanan Siak Sri Indrapura di Riau didirikan pada awal abad ke-18 oleh ....", options: ["Sultan Iskandar Muda", "Sultan Ageng Tirtayasa", "Raja Kecil", "Sultan Nuku"], answer: 2, solution: "1. Kesultanan Siak Sri Indrapura di Riau didirikan pada awal abad ke-18. 2. Pendirinya adalah Raja Kecil yang mengklaim sebagai keturunan Sultan Johor. 3. Di pesisir timur Sumatera pada masa Islam juga berkembang kesultanan Jambi, Palembang, dan Deli. 4. Jadi jawabannya Raja Kecil." },
    { q: "Bangsa Belanda pertama kali tiba di Nusantara pada tahun 1596 di bawah pimpinan Cornelis de Houtman. Pelabuhan pertama yang disinggahi rombongan Belanda tersebut adalah ....", options: ["Banten", "Jayakarta", "Malaka", "Ternate"], answer: 0, solution: "1. Cornelis de Houtman memimpin empat kapal Belanda (Hollandia, Mauritius, Amsterdam, dan Duyfken) berlayar mencari Kepulauan Rempah. 2. Rombongan itu tiba di Banten pada tahun 1596, menjadikannya kedatangan Belanda pertama di Nusantara. 3. Malaka saat itu dikuasai Portugis dan Ternate menjadi tujuan Spanyol-Portugis, sedangkan Jayakarta baru dikuasai Belanda puluhan tahun kemudian. 4. Jadi jawabannya Banten." },
    { q: "Tujuan awal kedatangan bangsa-bangsa Eropa ke Nusantara pada abad ke-16 dirumuskan dalam semboyan 3G, yaitu ....", options: ["Gold, Gospel, Game", "Gun, Gold, Glory", "Gold, Gospel, Glory", "Gospel, Garden, Gold"], answer: 2, solution: "1. Bangsa Eropa berlomba mencari daerah baru setelah jatuhnya Konstantinopel (1453) menutup jalur dagang rempah. 2. Semboyan 3G adalah: Gold (mencari kekayaan, terutama rempah-rempah), Gospel (menyebarkan agama Kristen), dan Glory (mencari kejayaan dan kekuasaan). 3. Pilihan lain mencampuradukkan istilah yang tidak dikenal dalam sejarah penjelajahan samudra. 4. Jadi jawabannya Gold, Gospel, Glory." },
    { q: "Portugis berhasil menguasai Malaka, pelabuhan dagang terpenting di Selat Malaka, pada tahun 1511 di bawah pimpinan ....", options: ["Vasco da Gama", "Alfonso de Albuquerque", "Francisco Serrao", "Ferdinand Magelhaens"], answer: 1, solution: "1. Malaka adalah pusat perdagangan rempah yang sangat strategis karena menguasai jalur pelayaran Selat Malaka. 2. Alfonso de Albuquerque memimpin serangan Portugis dan menaklukkan Malaka pada Agustus 1511. 3. Vasco da Gama hanya sampai India (1498), Francisco Serrao melanjutkan ke Maluku, sedangkan Magelhaens berlayar untuk Spanyol. 4. Jadi jawabannya Alfonso de Albuquerque." },
    { q: "Ferdinand Magelhaens yang disponsori Spanyol berlayar ke arah barat mencari Kepulauan Rempah. Setelah Magelhaens tewas di Filipina pada tahun 1521, pelayaran dilanjutkan oleh ....", options: ["Vasco da Gama", "Christopher Columbus", "Alfonso de Albuquerque", "Juan Sebastian Elcano"], answer: 3, solution: "1. Magelhaens berangkat tahun 1519 dan tiba di Kepulauan Rempah (Maluku) melalui rute barat. 2. Ia tewas dalam pertempuran di Mactan, Filipina, pada tahun 1521. 3. Juan Sebastian Elcano mengambil alih komando dan kembali ke Spanyol tahun 1522 dengan kapal Victoria, menuntaskan pelayaran keliling dunia pertama. 4. Jadi jawabannya Juan Sebastian Elcano." },
    { q: "Tokoh Inggris yang memimpin pelayaran dagang EIC pertama ke Nusantara dan berhasil memperoleh izin berdagang lada dari Sultan Aceh pada tahun 1602 adalah ....", options: ["Francis Drake", "James Lancaster", "Thomas Stamford Raffles", "William Hawkins"], answer: 1, solution: "1. East India Company (EIC) Inggris mengirim pelayaran dagang pertamanya ke Asia pada 1601. 2. James Lancaster memimpin rombongan itu dan tiba di Aceh tahun 1602, lalu memperoleh izin dagang lada dari Sultan Aceh. 3. Francis Drake memang singgah di Ternate (1579) saat mengelilingi dunia, tetapi bukan pemimpin pelayaran EIC; Raffles dan Hawkins berkaitan dengan masa yang berbeda. 4. Jadi jawabannya James Lancaster." },
    { q: "Gubernur Jenderal Herman Willem Daendels (1808-1811) membangun jalan sepanjang sekitar 1.000 km dari Anyer hingga Panarukan yang dikenal sebagai ....", options: ["Jalan Raya Pos", "Jalan Daendels", "Jalan Trans Jawa", "Jalan Raya Batavia"], answer: 0, solution: "1. Daendels diutus Prancis (Napoleon) untuk mempertahankan Jawa dari serangan Inggris. 2. Ia membangun Groote Postweg atau Jalan Raya Pos dari Anyer (Banten) sampai Panarukan (Jawa Timur) untuk keperluan pertahanan dan komunikasi. 3. Pembangunan ini dikerjakan dengan kerja rodi yang menelan banyak korban jiwa rakyat. 4. Jadi jawabannya Jalan Raya Pos." },
    { q: "Kekuasaan Belanda (di bawah Prancis) di Nusantara berakhir dan beralih ke tangan Inggris pada tahun 1811, yang ditandai dengan ....", options: ["Perjanjian Kalijati", "Traktat London", "Kapitulasi Tuntang", "Perjanjian Bongaya"], answer: 2, solution: "1. Inggris menyerang Jawa pada 1811 di bawah pimpinan Lord Minto dan Thomas Stamford Raffles. 2. Gubernur Jenderal Janssens (pengganti Daendels) menyerah dan menandatangani Kapitulasi Tuntang pada 18 September 1811. 3. Sejak itu Jawa dikuasai Inggris (1811-1816); Traktat London 1814 kemudian mengembalikannya ke Belanda, sedangkan Kalijati 1942 berkaitan dengan Jepang. 4. Jadi jawabannya Kapitulasi Tuntang." },
    { q: "Selama masa pemerintahan Inggris (1811-1816), Thomas Stamford Raffles menerapkan sistem sewa tanah (landrent). Selain kebijakan itu, Raffles juga dikenal karena ....", options: ["menulis buku History of Java dan merintis Kebun Raya Bogor", "membangun Jalan Raya Pos Anyer-Panarukan", "mencetuskan sistem tanam paksa", "menandatangani Perjanjian Bongaya"], answer: 0, solution: "1. Raffles memerintah Jawa sebagai Letnan Gubernur Inggris dan menerapkan landrent: petani membayar sewa tanah kepada pemerintah. 2. Ia menulis buku History of Java (1817) yang menjadi rujukan penting sejarah Jawa. 3. Ia juga merintis Kebun Raya Bogor pada tahun 1817. 4. Jadi jawabannya menulis buku History of Java dan merintis Kebun Raya Bogor." },
    { q: "Perbedaan pokok antara sistem sewa tanah (landrent) pada masa Raffles dan sistem tanam paksa (cultuurstelsel) pada masa Van den Bosch terletak pada ....", options: ["wilayah berlakunya di Jawa dan di luar Jawa", "ada tidaknya kerja paksa dalam pelaksanaannya", "pengelolaannya oleh swasta dan oleh pemerintah", "kewajiban membayar sewa tanah dan kewajiban menanam tanaman ekspor"], answer: 3, solution: "1. Pada sistem landrent, rakyat dianggap penyewa tanah pemerintah sehingga wajib membayar sewa (dalam bentuk uang atau hasil bumi). 2. Pada cultuurstelsel, rakyat wajib menyisihkan seperlima tanahnya untuk menanam tanaman dagangan (kopi, tebu, nila, tembakau) atau bekerja 66 hari. 3. Keduanya sama-sama memberatkan rakyat, tetapi bentuk kewajibannya berbeda secara mendasar. 4. Jadi jawabannya kewajiban membayar sewa tanah dan kewajiban menanam tanaman ekspor." },
    { q: "Ketentuan pokok Cultuurstelsel (1830) yang dicetuskan Gubernur Jenderal Van den Bosch antara lain rakyat wajib ....", options: ["menyerahkan seperlima tanahnya untuk tanaman wajib atau bekerja 66 hari", "menyerahkan seluruh hasil panen kepada pemerintah", "membayar pajak tanah sebesar separuh hasil panen", "menanam padi di seluruh tanah miliknya"], answer: 0, solution: "1. Cultuurstelsel diberlakukan 1830 untuk menutup defisit kas Belanda. 2. Ketentuan pokoknya: rakyat menyediakan seperlima tanah untuk tanaman dagangan (kopi, tebu, nila, tembakau), atau bila tanahnya sempit bekerja 66 hari; kelebihan hasil di atas pajak menjadi milik petani; gagal panen bukan karena kesalahan petani ditanggung pemerintah. 3. Ketentuan inilah yang kemudian banyak dilanggar dalam praktiknya. 4. Jadi jawabannya menyerahkan seperlima tanahnya untuk tanaman wajib atau bekerja 66 hari." },
    { q: "Dalam pelaksanaannya, Cultuurstelsel banyak menyimpang dari ketentuan pokoknya. Salah satu bentuk penyimpangan tersebut adalah ....", options: ["tanaman wajib diganti dengan tanaman padi", "waktu kerja dikurangi menjadi 30 hari", "tanah yang diambil melebihi seperlima dan hari kerja melebihi 66 hari", "seluruh hasil panen dikembalikan kepada petani"], answer: 2, solution: "1. Pengawasan pelaksanaan tanam paksa di lapangan sangat lemah. 2. Penyimpangannya antara lain: tanah yang dipakai melebihi seperlima (bahkan tanah terbaik), hari kerja melebihi 66 hari, dan kegagalan panen tetap dibebankan kepada petani. 3. Akibatnya penderitaan rakyat jauh lebih berat daripada yang tertulis dalam aturan. 4. Jadi jawabannya tanah yang diambil melebihi seperlima dan hari kerja melebihi 66 hari." },
    { q: "Dampak pelaksanaan Cultuurstelsel bagi Belanda dan bagi rakyat Indonesia adalah ....", options: ["Belanda merugi tetapi rakyat semakin sejahtera", "kas Belanda surplus (batig slot) tetapi rakyat menderita kelaparan dan kemiskinan", "perekonomian Belanda stagnan dan rakyat tidak terpengaruh", "Belanda bangkrut dan rakyat bebas dari pajak"], answer: 1, solution: "1. Dampak positifnya (bagi Belanda): kas negara surplus besar (batig slot) serta dibangunnya jalan, jembatan, waduk, dan pabrik gula; rakyat mengenal tanaman dagangan baru. 2. Dampak negatifnya (bagi rakyat): penderitaan, kelaparan, kemiskinan, dan kematian, misalnya bencana kelaparan di Cirebon (1843) dan Demak (1849-1850). 3. Ketimpangan inilah yang memicu kritik keras dari kaum humanis Belanda. 4. Jadi jawabannya kas Belanda surplus (batig slot) tetapi rakyat menderita kelaparan dan kemiskinan." },
    { q: "Undang-Undang Agraria 1870 menjadi tonggak dimulainya politik pintu terbuka (politik liberal) di Hindia Belanda karena isinya ....", options: ["menghapus seluruh pajak yang dibebankan kepada rakyat", "melarang modal asing menanam modal di Hindia Belanda", "menyerahkan seluruh tanah kepada rakyat pribumi", "membuka kesempatan bagi modal swasta menyewa tanah dari pemerintah"], answer: 3, solution: "1. Desakan kaum liberal Belanda menghendaki swasta diberi peran dalam perekonomian Hindia Belanda. 2. UU Agraria 1870 menetapkan tanah milik pemerintah dapat disewa pihak swasta (hak erfpacht hingga 75 tahun). 3. Sejak itu modal swasta Belanda dan asing berbondong-bondong membuka perkebunan: inilah yang disebut politik pintu terbuka. 4. Jadi jawabannya membuka kesempatan bagi modal swasta menyewa tanah dari pemerintah." },
    { q: "Undang-Undang Gula 1870 yang dikeluarkan pemerintah kolonial mengatur tentang ....", options: ["penghapusan bertahap monopoli gula pemerintah dan penyerahannya kepada swasta", "penetapan harga gula yang seragam di seluruh Hindia Belanda", "larangan rakyat menanam tebu di tanahnya", "kewajiban menanam tebu di seperlima tanah rakyat"], answer: 0, solution: "1. Gula adalah salah satu komoditas utama tanam paksa yang dikelola pemerintah. 2. UU Gula 1870 mengatur penghapusan monopoli gula pemerintah secara bertahap dalam 12 tahun dan menyerahkan pengelolaannya kepada pihak swasta. 3. Kebijakan ini sejalan dengan semangat liberal politik pintu terbuka. 4. Jadi jawabannya penghapusan bertahap monopoli gula pemerintah dan penyerahannya kepada swasta." },
    { q: "Perang Padri (1803-1837) pada awalnya dipicu oleh pertentangan antara ....", options: ["rakyat Minangkabau dan VOC", "kaum adat dan kaum Paderi", "kaum bangsawan dan rakyat jelata", "umat Islam dan kaum Kristen"], answer: 1, solution: "1. Sekembali dari Mekah (1803), Haji Miskin, Haji Sumanik, dan Haji Piobang membawa paham pembaruan (Wahabi) dan membentuk kaum Paderi. 2. Kaum Paderi menentang kebiasaan kaum adat seperti sabung ayam, minuman keras, dan mengunyah sirih sehingga terjadi konflik adat versus Paderi. 3. Belanda kemudian ikut campur dan perang berubah menjadi perlawanan rakyat Minangkabau melawan Belanda. 4. Jadi jawabannya kaum adat dan kaum Paderi." },
    { q: "Tokoh pemimpin Perang Padri yang bertahan di Benteng Bonjol dan akhirnya menyerah kepada Belanda pada tahun 1837 adalah ....", options: ["Tuanku Imam Bonjol", "Tuanku Nan Renceh", "Haji Miskin", "Datuk Bandaro"], answer: 0, solution: "1. Tuanku Imam Bonjol (Muhammad Syahab) adalah pemimpin kharismatik kaum Paderi yang berpusat di Bonjol. 2. Belanda menerapkan strategi Benteng (mirip benteng stelsel) hingga Benteng Bonjol jatuh pada Agustus 1837. 3. Imam Bonjol ditangkap pada Oktober 1837 dan diasingkan (Cianjur, Ambon, Minahasa) hingga wafat 1864. 4. Jadi jawabannya Tuanku Imam Bonjol." },
    { q: "Sebab khusus meletusnya Perang Diponegoro atau Perang Jawa (1825-1830) adalah ....", options: ["penangkapan Pangeran Diponegoro oleh Belanda", "penghapusan sistem tanam paksa", "pemasangan patok jalan oleh Belanda melewati makam leluhur Diponegoro di Tegalrejo", "serangan Belanda ke Keraton Yogyakarta"], answer: 2, solution: "1. Sebab umum perang ini adalah campur tangan Belanda dalam urusan keraton, pajak yang memberatkan, dan penderitaan rakyat. 2. Sebab khususnya (pemicu langsung): Belanda memasang patok-patok untuk pembangunan jalan yang melewati tanah dan makam leluhur Diponegoro di Tegalrejo. 3. Diponegoro mencabuti patok itu sehingga pecah perang terbuka pada 20 Juli 1825. 4. Jadi jawabannya pemasangan patok jalan oleh Belanda melewati makam leluhur Diponegoro di Tegalrejo." },
    { q: "Untuk menghadapi taktik gerilya Pangeran Diponegoro, Belanda di bawah pimpinan Jenderal De Kock menerapkan strategi ....", options: ["Benteng Stelsel", "devide et impera", "pelayaran Hongi", "politik etis"], answer: 0, solution: "1. Diponegoro menggunakan taktik gerilya dengan basis di daerah pegunungan dan mendapat dukungan luas rakyat. 2. De Kock membalas dengan Benteng Stelsel: membangun benteng-benteng di daerah yang direbut untuk mempersempit ruang gerak pasukan Diponegoro. 3. Strategi ini berhasil; Diponegoro ditangkap saat perundingan di Magelang pada 28 Maret 1830 dan diasingkan ke Manado lalu Makassar. 4. Jadi jawabannya Benteng Stelsel." },
    { q: "Panglima perang kepercayaan Pangeran Diponegoro yang bergelar Pangeran Mangkubumi dan memimpin pasukan elit adalah ....", options: ["Kyai Mojo", "Pangeran Diponegoro", "Hamengkubuwono II", "Sentot Prawirodirdjo"], answer: 3, solution: "1. Sentot Ali Basah Prawirodirdjo adalah panglima muda yang sangat dipercaya Diponegoro dan diangkat menjadi Pangeran Mangkubumi. 2. Ia memimpin pasukan elit dan beberapa kali memukul mundur Belanda. 3. Kyai Mojo adalah penasihat spiritual Diponegoro, bukan panglima perangnya; Sentot akhirnya menyerah pada 1829. 4. Jadi jawabannya Sentot Prawirodirdjo." },
    { q: "Tokoh ulama yang menjadi penasihat spiritual Pangeran Diponegoro selama Perang Jawa (1825-1830) adalah ....", options: ["Sentot Prawirodirdjo", "Kyai Mojo", "Pangeran Notokusumo", "Kyai Hasan Besari"], answer: 1, solution: "1. Kyai Mojo adalah ulama karismatik yang menjadi penasihat spiritual dan pemberi legitimasi keagamaan bagi perjuangan Diponegoro. 2. Kehadirannya membuat perang ini juga bercorak perang sabil (perang suci). 3. Kyai Mojo menyerah pada 1828 dan diasingkan ke Tondano, Minahasa. 4. Jadi jawabannya Kyai Mojo." },
    { q: "Perang Diponegoro menelan biaya yang sangat besar hingga menguras kas Belanda. Kondisi inilah yang melatarbelakangi ....", options: ["diberlakukannya Cultuurstelsel oleh Van den Bosch pada tahun 1830", "dicanangkannya Politik Etis pada tahun 1901", "lahirnya Undang-Undang Agraria 1870", "didirikannya VOC pada tahun 1602"], answer: 0, solution: "1. Perang Jawa berlangsung lima tahun dan menelan biaya sekitar 20 juta gulden serta ribuan tentara Belanda tewas. 2. Kas Belanda defisit, diperparah dengan memisahkan dirinya Belgia pada 1830. 3. Untuk mengisi kas negara dengan cepat, Van den Bosch mencetuskan Cultuurstelsel (tanam paksa) pada 1830. 4. Jadi jawabannya diberlakukannya Cultuurstelsel oleh Van den Bosch pada tahun 1830." },
    { q: "Perang Pattimura meletus pada tahun 1817 di Maluku. Benteng Belanda yang berhasil direbut pasukan Kapitan Pattimura di Saparua adalah ....", options: ["Benteng Victoria", "Benteng Amsterdam", "Benteng Duurstede", "Benteng Rotterdam"], answer: 2, solution: "1. Setelah Inggris menyerahkan Maluku kembali ke Belanda, rakyat Maluku menderita akibat monopoli dan kerja paksa. 2. Kapitan Pattimura (Thomas Matulessy) memimpin serangan dan merebut Benteng Duurstede di Saparua pada 16 Mei 1817; Residen Van den Berg tewas. 3. Perlawanan akhirnya dipadamkan dan Pattimura dihukum gantung pada 16 Desember 1817. 4. Jadi jawabannya Benteng Duurstede." },
    { q: "Perang Banjar (1859-1862) dipimpin oleh Pangeran Antasari. Latar belakang perlawanan ini berkaitan dengan ....", options: ["Wasiat Sultan Sulaiman yang dilanggar Belanda dalam pengangkatan sultan", "monopoli perdagangan lada oleh VOC", "pemasangan patok jalan oleh Belanda", "penutupan pelabuhan Banjarmasin oleh Belanda"], answer: 0, solution: "1. Wasiat Sultan Sulaiman menetapkan Abdul Rakhman sebagai pengganti Sultan Adam. 2. Belanda justru mengangkat Tamjidillah yang didukungnya, sehingga menimbulkan kemarahan rakyat Banjar. 3. Pangeran Antasari memimpin perlawanan rakyat sejak 1859 hingga wafat karena cacar pada 1862. 4. Jadi jawabannya Wasiat Sultan Sulaiman yang dilanggar Belanda dalam pengangkatan sultan." },
    { q: "Teuku Umar terkenal dengan siasat cerdiknya dalam Perang Aceh, yaitu ....", options: ["menyerang langsung benteng Belanda di Banda Aceh", "meminta bantuan pasukan Turki Usmani", "menandatangani perjanjian damai jangka panjang", "pura-pura menyerah dan bekerja sama dengan Belanda, lalu berbalik menyerang"], answer: 3, solution: "1. Pada 1893 Teuku Umar menyatakan menyerah dan diberi gelar Johan Pahlawan beserta pasukan dan senjata oleh Belanda. 2. Pada 1896 ia berbalik menyerang Belanda dengan membawa lari senjata-senjata rampasan itu. 3. Siasat ini sangat merugikan Belanda; Teuku Umar gugur dalam pertempuran di Meulaboh pada 1899. 4. Jadi jawabannya pura-pura menyerah dan bekerja sama dengan Belanda, lalu berbalik menyerang." },
    { q: "Snouck Hurgronje adalah penasihat pemerintah kolonial yang merumuskan strategi menaklukkan Aceh. Inti nasihatnya adalah ....", options: ["memisahkan Islam dan adat: menaklukkan golongan ulama dan merangkul golongan adat", "membakar seluruh masjid yang ada di Aceh", "menarik seluruh pasukan Belanda dari Aceh", "memberikan kemerdekaan kepada Kerajaan Aceh"], answer: 0, solution: "1. Snouck Hurgronje meneliti masyarakat Aceh dan menyimpulkan perlawanan digerakkan oleh ulama, bukan raja. 2. Nasihatnya: Islam sebagai kekuatan politik harus ditaklukkan, sedangkan golongan adat dirangkul. 3. Saran ini dijalankan Gubernur Militer Van Heutsz dengan pasukan Marsose hingga Aceh takluk. 4. Jadi jawabannya memisahkan Islam dan adat: menaklukkan golongan ulama dan merangkul golongan adat." },
    { q: "Pahlawan perempuan Aceh yang melanjutkan perjuangan suaminya, Teuku Umar, setelah suaminya gugur pada 1899 adalah ....", options: ["Cut Nyak Meutia", "Cut Nyak Dien", "Pocut Baren", "Teungku Fakinah"], answer: 1, solution: "1. Cut Nyak Dien adalah istri Teuku Umar yang ikut berjuang di medan perang. 2. Setelah Teuku Umar gugur (1899), ia terus memimpin perlawanan gerilya hingga ditangkap Belanda pada 1905. 3. Ia diasingkan ke Sumedang, Jawa Barat, dan wafat di sana pada 1908. 4. Jadi jawabannya Cut Nyak Dien." },
    { q: "Pada awal Perang Aceh, Belanda membakar Masjid Raya Baiturrahman di Banda Aceh. Tindakan tersebut justru berakibat ....", options: ["rakyat Aceh segera menyerah kepada Belanda", "Perang Aceh berakhir dalam sekejap", "membakar semangat jihad rakyat Aceh melawan Belanda", "Belanda meraih kemenangan total"], answer: 2, solution: "1. Pada serangan kedua tahun 1874, Belanda membakar Masjid Raya Baiturrahman saat merebut Banda Aceh. 2. Tindakan itu melukai perasaan keagamaan rakyat Aceh sehingga semangat jihad melawan Belanda justru berkobar lebih hebat. 3. Belanda kemudian membangun kembali masjid tersebut untuk menarik simpati rakyat Aceh. 4. Jadi jawabannya membakar semangat jihad rakyat Aceh melawan Belanda." },
    { q: "Pemimpin Perang Batak yang gigih melawan Belanda dan gugur pada tahun 1907 adalah ....", options: ["Sutan Malim", "Sisingamangaraja XII", "Raja Pontas", "Datuk Baringin"], answer: 1, solution: "1. Sisingamangaraja XII memimpin perlawanan rakyat Batak terhadap ekspansi Belanda sejak 1878. 2. Ia menggunakan taktik gerilya di pedalaman Tapanuli selama hampir 30 tahun. 3. Ia gugur dalam pertempuran di Dairi pada 17 Juni 1907, menandai berakhirnya Perang Batak. 4. Jadi jawabannya Sisingamangaraja XII." },
    { q: "Perang Puputan di Bali adalah perlawanan habis-habisan hingga titik darah penghabisan. Puputan Badung terjadi pada tahun 1906, sedangkan Puputan Klungkung terjadi pada tahun ....", options: ["1908", "1906", "1849", "1945"], answer: 0, solution: "1. Puputan berarti perang habis-habisan: lebih baik mati daripada menyerah kepada Belanda. 2. Puputan Badung dipimpin I Gusti Ngurah Made Agung pada 20 September 1906. 3. Puputan Klungkung dipimpin Dewa Agung Jambe pada 28 April 1908; sebelumnya terjadi Puputan Jagaraga (1848-1849) di Buleleng. 4. Jadi jawabannya 1908." },
    { q: "Untung Suropati dan Trunojoyo adalah tokoh perlawanan terhadap VOC di Jawa pada abad ke-17. Persamaan perjuangan keduanya adalah ....", options: ["memimpin pasukan perang di Maluku", "menjadi sekutu setia VOC", "berjuang di Sumatera Barat", "melawan dominasi VOC di Jawa Timur"], answer: 3, solution: "1. Trunojoyo memberontak (1674-1680) terhadap Amangkurat I yang bersekutu dengan VOC dan sempat menguasai Jawa Timur. 2. Untung Suropati, bekas budak VOC, memberontak pada 1684 dan menjadi penguasa Pasuruan yang melawan VOC hingga gugur pada 1706. 3. Keduanya berjuang di Jawa Timur menentang dominasi VOC beserta sekutu-sekutunya. 4. Jadi jawabannya melawan dominasi VOC di Jawa Timur." },
    { q: "Pelayaran Hongi yang rutin dilakukan VOC di perairan Maluku bertujuan untuk ....", options: ["mencari daerah penghasil emas yang baru", "mengawasi pelaksanaan monopoli perdagangan rempah", "mengangkut pasukan VOC ke Batavia", "menjalin persahabatan dengan raja-raja Maluku"], answer: 1, solution: "1. VOC menerapkan monopoli perdagangan rempah (cengkeh dan pala) di Maluku. 2. Pelayaran Hongi adalah patroli bersenjata dengan perahu kora-kora untuk mengawasi dan menindak pelanggaran monopoli. 3. Dalam patroli ini VOC juga menjalankan ekstirpasi, yaitu pemusnahan pohon rempah di luar wilayah yang diizinkan. 4. Jadi jawabannya mengawasi pelaksanaan monopoli perdagangan rempah." },
    { q: "Politik devide et impera yang diterapkan Belanda di Nusantara berarti ....", options: ["politik adu domba untuk memecah belah dan menguasai", "politik balas budi kepada rakyat jajahan", "politik pintu terbuka bagi modal asing", "politik tanam paksa tanaman ekspor"], answer: 0, solution: "1. Devide et impera berasal dari bahasa Latin yang berarti pecah belah lalu kuasai (divide and rule). 2. Belanda memanfaatkan dan mengadu domba konflik antarkerajaan atau antarkelompok pribumi agar mudah dikuasai. 3. Contohnya: memanfaatkan perpecahan Mataram (Perjanjian Giyanti 1755) dan konflik suksesi di Banjar. 4. Jadi jawabannya politik adu domba untuk memecah belah dan menguasai." },
    { q: "Tokoh Belanda yang menulis artikel Een Eereschuld (Utang Kehormatan) pada tahun 1899 dan menuntut politik balas budi kepada rakyat Hindia Belanda adalah ....", options: ["Johannes van den Bosch", "Eduard Douwes Dekker", "Conrad van Deventer", "Herman Daendels"], answer: 2, solution: "1. Conrad van Deventer menulis artikel Een Eereschuld di majalah De Gids (1899). 2. Ia menyatakan Belanda berutang budi (utang kehormatan) kepada rakyat Hindia Belanda atas keuntungan besar tanam paksa dan menuntut balas budi. 3. Kritik serupa juga disuarakan kaum liberal seperti Fransen van de Putte, sedangkan Douwes Dekker menulis Max Havelaar. 4. Jadi jawabannya Conrad van Deventer." },
    { q: "Salah satu dampak positif Politik Etis bagi bangsa Indonesia adalah ....", options: ["munculnya golongan terpelajar yang memelopori pergerakan nasional", "berakhirnya seluruh bentuk kerja paksa kolonial", "tercapainya kemerdekaan Indonesia tahun 1901", "dihapuskannya seluruh pajak kolonial"], answer: 0, solution: "1. Program edukasi dalam Politik Etis membuka akses pendidikan Barat bagi pribumi (STOVIA, HIS, MULO, dan sebagainya). 2. Lahirlah golongan terpelajar (kaum intelektual) Indonesia. 3. Golongan inilah yang kemudian memelopori organisasi pergerakan nasional seperti Budi Utomo (1908). 4. Jadi jawabannya munculnya golongan terpelajar yang memelopori pergerakan nasional." },
    { q: "Volksraad yang dibentuk oleh pemerintah kolonial Belanda pada tahun 1918 adalah ....", options: ["tentara sukarela bentukan Jepang", "organisasi kepemudaan Indonesia", "partai politik milik Belanda", "dewan perwakilan rakyat Hindia Belanda"], answer: 3, solution: "1. Volksraad berarti Dewan Rakyat, dibentuk pada 1918 sebagai lembaga perwakilan semi-parlementer di Hindia Belanda. 2. Anggotanya terdiri atas orang Belanda, Timur Asing, dan pribumi (meski jumlah pribumi terbatas). 3. Melalui Volksraad, tokoh seperti Moh. Husni Thamrin menyuarakan tuntutan Indonesia berparlemen. 4. Jadi jawabannya dewan perwakilan rakyat Hindia Belanda." },
    { q: "Pada masa pendudukan Jepang, rakyat Indonesia dipaksa bekerja untuk kepentingan perang Jepang. Kerja paksa tersebut dikenal dengan istilah ....", options: ["jugun ianfu", "romusha", "kinrohoshi", "seikerei"], answer: 1, solution: "1. Jepang membutuhkan tenaga kerja besar untuk proyek perang seperti pembangunan jalan dan rel kereta. 2. Rakyat dipaksa menjadi romusha dan banyak yang dikirim ke luar Jawa (Burma, Siam, Malaya); ribuan tewas karena kerja berat dan kurang makan. 3. Jugun ianfu adalah sebutan untuk perempuan penghibur, sedangkan seikerei adalah kewajiban hormat ke arah Tokyo. 4. Jadi jawabannya romusha." },
    { q: "PETA (Pembela Tanah Air) yang dibentuk Jepang pada tahun 1943 adalah ....", options: ["barisan pemuda untuk latihan militer", "organisasi perempuan pendukung perang", "tentara sukarela pribumi untuk membantu Jepang", "polisi rahasia bentukan Jepang"], answer: 2, solution: "1. PETA dibentuk Jepang pada 1943 sebagai tentara sukarela yang beranggotakan pemuda pribumi. 2. Tujuannya membantu Jepang menghadapi Sekutu, tetapi pelatihannya melahirkan perwira-perwira Indonesia seperti Soedirman dan Gatot Subroto. 3. Di Sumatera pasukan sejenis bernama Giyugun; Seinendan adalah barisan pemuda dan Keibodan barisan pembantu polisi. 4. Jadi jawabannya tentara sukarela pribumi untuk membantu Jepang." },
    { q: "Janji kemerdekaan Indonesia yang diucapkan Perdana Menteri Jepang Koiso di depan parlemen Jepang terjadi pada ....", options: ["8 Maret 1942", "17 Agustus 1945", "7 September 1944", "29 April 1945"], answer: 2, solution: "1. Setelah menderita kekalahan beruntun di Pasifik, Jepang membutuhkan dukungan rakyat Indonesia. 2. PM Koiso menjanjikan kemerdekaan bagi Indonesia pada 7 September 1944. 3. Janji ini ditindaklanjuti dengan pembentukan BPUPKI pada 29 April 1945 untuk menyelidiki usaha-usaha persiapan kemerdekaan. 4. Jadi jawabannya 7 September 1944." },
    { q: "Faktor pendorong pergerakan nasional Indonesia yang berasal dari dalam negeri adalah ....", options: ["kemenangan Jepang atas Rusia", "pendidikan Barat yang melahirkan kaum terpelajar", "berdirinya Turki Modern", "kemenangan Sekutu pada Perang Dunia I"], answer: 1, solution: "1. Pergerakan nasional muncul karena faktor pendorong dari dalam negeri dan dari luar negeri. 2. Faktor dari dalam negeri antara lain penderitaan rakyat akibat penjajahan dan munculnya kaum terpelajar hasil pendidikan Barat. 3. Kemenangan Jepang atas Rusia dan gerakan Turki Muda justru faktor dari luar negeri. 4. Jadi jawabannya pendidikan Barat yang melahirkan kaum terpelajar." },
    { q: "Kemenangan Jepang atas Rusia pada tahun 1905 mendorong pergerakan nasional Indonesia karena ....", options: ["Jepang memberi bantuan senjata kepada pejuang Indonesia", "bangsa Asia terbukti mampu mengalahkan bangsa Eropa", "Rusia menjadi sekutu rakyat Indonesia", "Jepang membuka banyak sekolah di Indonesia"], answer: 1, solution: "1. Pada awal abad ke-20 bangsa Asia umumnya merasa rendah diri terhadap bangsa Eropa. 2. Jepang yang merupakan bangsa Asia berhasil mengalahkan Rusia yang bangsa Eropa dalam perang tahun 1904-1905. 3. Kemenangan ini membangkitkan kepercayaan diri bangsa-bangsa Asia, termasuk Indonesia, bahwa penjajah Eropa bisa dilawan. 4. Jadi jawabannya bangsa Asia terbukti mampu mengalahkan bangsa Eropa." },
    { q: "Pergerakan Turki Muda yang menjadi inspirasi pergerakan nasional Indonesia adalah gerakan ....", options: ["melawan kekuasaan Inggris di Mesir", "kaum muda Turki menentang kekuasaan absolut Sultan", "perebutan Konstantinopel oleh bangsa Arab", "pemberontakan petani di Anatolia"], answer: 1, solution: "1. Turki Muda adalah gerakan kaum intelektual dan perwira muda Turki pada awal abad ke-20. 2. Mereka menentang kekuasaan absolut Sultan Abdul Hamid II dan menuntut pembaruan. 3. Keberhasilan gerakan ini mengilhami kaum pergerakan di Indonesia untuk berorganisasi menentang penjajahan. 4. Jadi jawabannya kaum muda Turki menentang kekuasaan absolut Sultan." },
    { q: "Tokoh pergerakan nasional Filipina yang menjadi inspirasi para pejuang Indonesia adalah ....", options: ["Jose Rizal", "Sun Yat Sen", "Mahatma Gandhi", "Kemal Ataturk"], answer: 0, solution: "1. Bangsa-bangsa Asia yang lebih dulu bergerak melawan penjajah menjadi teladan bagi Indonesia. 2. Filipina bergerak melawan Spanyol dan Amerika Serikat pada akhir abad ke-19. 3. Jose Rizal adalah tokoh pergerakan Filipina yang gigih melawan penjajahan Spanyol melalui tulisan dan organisasi. 4. Jadi jawabannya Jose Rizal." },
    { q: "Gagasan pendirian Budi Utomo dicetuskan oleh ....", options: ["dr. Sutomo", "dr. Wahidin Sudirohusodo", "Ki Hajar Dewantara", "Tjipto Mangoenkoesoemo"], answer: 1, solution: "1. Gagasan mendirikan organisasi untuk kemajuan bangsa dicetuskan dr. Wahidin Sudirohusodo setelah berkeliling Jawa menggalang dana beasiswa. 2. Gagasan itu lalu diwujudkan oleh para pelajar STOVIA yang memilih dr. Sutomo sebagai ketua pertama. 3. Ki Hajar Dewantara dan Tjipto adalah tokoh Indische Partij, bukan pencetus Budi Utomo. 4. Jadi jawabannya dr. Wahidin Sudirohusodo." },
    { q: "Sarekat Dagang Islam (SDI) didirikan oleh H. Samanhudi di Solo pada tahun 1911 dengan tujuan awal ....", options: ["memperjuangkan kemerdekaan politik", "melindungi pedagang batik pribumi dari persaingan pedagang Tionghoa", "menyebarkan agama Islam ke seluruh Jawa", "mendirikan sekolah-sekolah Islam"], answer: 1, solution: "1. H. Samanhudi adalah pedagang batik di Solo yang prihatin melihat pedagang pribumi tersisih. 2. Ia mendirikan Sarekat Dagang Islam pada 1911 sebagai wadah melindungi pedagang batik pribumi dari persaingan pedagang Tionghoa. 3. SDI kemudian berkembang menjadi Sarekat Islam yang bergerak di bidang politik di bawah Tjokroaminoto. 4. Jadi jawabannya melindungi pedagang batik pribumi dari persaingan pedagang Tionghoa." },
    { q: "Tokoh yang memimpin Sarekat Islam dan dijuluki Raja Jawa tanpa mahkota adalah ....", options: ["H. Samanhudi", "H.O.S. Tjokroaminoto", "Semaun", "Darsono"], answer: 1, solution: "1. Setelah SDI berubah menjadi Sarekat Islam, kepemimpinannya dipegang H.O.S. Tjokroaminoto. 2. Di bawah pimpinannya SI berkembang pesat menjadi organisasi massa terbesar dengan ratusan ribu anggota. 3. Pengaruhnya yang sangat besar membuat rakyat menjulukinya Raja Jawa tanpa mahkota. 4. Jadi jawabannya H.O.S. Tjokroaminoto." },
    { q: "Sarekat Islam terpecah menjadi SI Putih dan SI Merah pada tahun 1921 karena ....", options: ["perbedaan pandangan tentang bentuk negara", "penyusupan paham komunis ke dalam tubuh SI", "perselisihan soal kepemimpinan Tjokroaminoto", "tekanan pemerintah Belanda membubarkan SI"], answer: 1, solution: "1. Sarekat Islam awalnya menampung berbagai aliran, termasuk kelompok berhaluan komunis pimpinan Semaun dan Darsono. 2. Kelompok ini menyusupkan paham komunis ke dalam SI sehingga menimbulkan pertentangan dengan kelompok Islam pimpinan Tjokroaminoto. 3. Pada 1921 SI pecah menjadi SI Putih (Islam, Tjokroaminoto) dan SI Merah (komunis, Semaun). 4. Jadi jawabannya penyusupan paham komunis ke dalam tubuh SI." },
    { q: "Indische Partij yang didirikan tahun 1912 dipimpin oleh Tiga Serangkai, yaitu ....", options: ["Soekarno, Hatta, dan Sjahrir", "Douwes Dekker, Tjipto Mangunkusumo, dan Ki Hajar Dewantara", "Tjokroaminoto, Agus Salim, dan Muis", "Sutomo, Wahidin, dan Cipto"], answer: 1, solution: "1. Indische Partij adalah partai politik pertama di Indonesia yang berhaluan nasionalisme Hindia. 2. Partai ini didirikan pada tahun 1912 oleh tiga tokoh yang dikenal sebagai Tiga Serangkai. 3. Ketiganya adalah Ernest Douwes Dekker, dr. Tjipto Mangunkusumo, dan Suwardi Suryaningrat (Ki Hajar Dewantara). 4. Jadi jawabannya Douwes Dekker, Tjipto Mangunkusumo, dan Ki Hajar Dewantara." },
    { q: "Artikel berjudul Seandainya Aku Seorang Belanda tahun 1913 yang mengecam perayaan kemerdekaan Belanda di tanah jajahan ditulis oleh ....", options: ["Douwes Dekker", "Tjipto Mangunkusumo", "Ki Hajar Dewantara", "Tirto Adhi Soerjo"], answer: 2, solution: "1. Pemerintah kolonial merayakan 100 tahun kemerdekaan Belanda dari Perancis dan memungut biaya dari rakyat jajahan. 2. Ki Hajar Dewantara menulis artikel pedas berjudul Seandainya Aku Seorang Belanda yang dimuat di surat kabar De Expres. 3. Akibat artikel itu ia dibuang ke Belanda bersama dua rekannya sesama Tiga Serangkai. 4. Jadi jawabannya Ki Hajar Dewantara." },
    { q: "Tokoh yang menjadi pemimpin Perhimpunan Indonesia di Belanda adalah ....", options: ["Soekarno", "Mohammad Hatta", "Sutan Sjahrir", "Agus Salim"], answer: 1, solution: "1. Perhimpunan Indonesia adalah organisasi para pelajar Indonesia di Belanda. 2. Di bawah pimpinan Mohammad Hatta, PI berubah menjadi organisasi yang berhaluan politik dan menuntut kemerdekaan Indonesia. 3. PI menerbitkan majalah Indonesia Merdeka sebagai corong perjuangannya. 4. Jadi jawabannya Mohammad Hatta." },
    { q: "Isi pokok Sumpah Perhimpunan Indonesia tahun 1925 adalah ....", options: ["Indonesia harus menjadi bagian kerajaan Belanda", "tanah air Indonesia, bangsa Indonesia, dan bahasa Indonesia", "perjuangan kemerdekaan hanya melalui parlemen", "kerja sama penuh dengan pemerintah kolonial"], answer: 1, solution: "1. Perhimpunan Indonesia adalah organisasi pelajar Indonesia di negeri Belanda. 2. Pada tahun 1925 PI mengeluarkan manifesto politik yang dikenal sebagai Sumpah PI. 3. Isinya menegaskan tiga kesatuan: tanah air Indonesia, bangsa Indonesia, dan bahasa Indonesia sebagai bahasa persatuan. 4. Jadi jawabannya tanah air Indonesia, bangsa Indonesia, dan bahasa Indonesia." },
    { q: "Asas perjuangan Partai Nasional Indonesia (PNI) yang didirikan Soekarno di Bandung adalah ....", options: ["nasionalisme agama", "marhaenisme", "sosialisme Islam", "kooperasi dengan Belanda"], answer: 1, solution: "1. PNI didirikan Soekarno di Bandung pada tahun 1927 sebagai partai berhaluan nasionalisme radikal. 2. Asas perjuangannya adalah marhaenisme, yaitu paham yang membela kaum marhaen atau rakyat kecil yang miskin akibat penjajahan. 3. PNI bersikap non-kooperasi, menolak bekerja sama dengan pemerintah kolonial Belanda. 4. Jadi jawabannya marhaenisme." },
    { q: "Pledoi berjudul Indonesia Menggugat dibacakan Soekarno pada tahun 1930 di hadapan ....", options: ["Volksraad di Batavia", "Landraad atau pengadilan di Bandung", "parlemen Belanda di Den Haag", "sidang BPUPKI di Jakarta"], answer: 1, solution: "1. Pemerintah kolonial menangkap Soekarno dan para pemimpin PNI karena kegiatan politiknya. 2. Mereka diadili di Landraad (pengadilan negeri) Bandung pada tahun 1930. 3. Dalam pembelaannya Soekarno membacakan pledoi terkenal berjudul Indonesia Menggugat yang justru menyerang balik penjajahan Belanda. 4. Jadi jawabannya Landraad atau pengadilan di Bandung." },
    { q: "Setelah PNI dibubarkan, Soekarno mendirikan Partindo sedangkan Mohammad Hatta dan Sutan Sjahrir mendirikan ....", options: ["PNI-Baru", "Parindra", "Gerindo", "Partai Sarekat Islam"], answer: 0, solution: "1. Pemerintah kolonial membubarkan PNI pada tahun 1931 karena dianggap membahayakan kekuasaan Belanda. 2. Para tokohnya lalu menempuh jalan berbeda: Soekarno mendirikan Partindo (Partai Indonesia). 3. Sementara itu Mohammad Hatta dan Sutan Sjahrir mendirikan PNI-Baru yang berhaluan pendidikan kader. 4. Jadi jawabannya PNI-Baru." },
    { q: "Taman Siswa didirikan Ki Hajar Dewantara pada tahun 1922 dengan semboyan pendidikan ....", options: ["Bhinneka Tunggal Ika", "Tut Wuri Handayani", "Satyam Eva Jayate", "Bhineka Tunggal Ika"], answer: 1, solution: "1. Ki Hajar Dewantara mendirikan Taman Siswa di Yogyakarta pada 3 Juli 1922 sebagai lembaga pendidikan nasional. 2. Taman Siswa menentang sistem pendidikan kolonial yang diskriminatif terhadap pribumi. 3. Semboyannya adalah Tut Wuri Handayani yang artinya dari belakang memberi dorongan semangat. 4. Jadi jawabannya Tut Wuri Handayani." },
    { q: "Muhammadiyah didirikan K.H. Ahmad Dahlan di Yogyakarta pada tahun 1912 dengan tujuan utama ....", options: ["memurnikan ajaran Islam dari takhayul dan khurafat", "melawan Belanda dengan kekuatan senjata", "mendirikan negara Islam", "menggabungkan adat dengan syariat"], answer: 0, solution: "1. K.H. Ahmad Dahlan melihat banyak praktik keagamaan umat Islam yang bercampur takhayul dan khurafat. 2. Ia mendirikan Muhammadiyah di Yogyakarta pada 18 November 1912 sebagai gerakan pembaruan Islam. 3. Tujuannya memurnikan ajaran Islam kembali kepada Alquran dan hadis melalui pendidikan dan dakwah. 4. Jadi jawabannya memurnikan ajaran Islam dari takhayul dan khurafat." },
    { q: "Nahdlatul Ulama (NU) didirikan di Surabaya pada tahun 1926 atas prakarsa ....", options: ["K.H. Ahmad Dahlan", "K.H. Hasyim Asy'ari", "K.H. Mas Mansyur", "K.H. Wahid Hasyim"], answer: 1, solution: "1. Nahdlatul Ulama didirikan di Surabaya pada 31 Januari 1926 oleh para ulama pesantren. 2. Prakarsa pendiriannya datang dari K.H. Hasyim Asy'ari, ulama besar pendiri Pondok Pesantren Tebuireng. 3. NU bertujuan mempertahankan tradisi keislaman ahlussunnah wal jamaah sekaligus berperan dalam pergerakan nasional. 4. Jadi jawabannya K.H. Hasyim Asy'ari." },
    { q: "Gabungan Politik Indonesia (GAPI) yang dibentuk pada tahun 1939 menuntut ....", options: ["kemerdekaan penuh segera", "Indonesia Berparlemen", "pembubaran Volksraad", "pemerintahan militer Jepang"], answer: 1, solution: "1. GAPI dibentuk pada 21 Mei 1939 sebagai gabungan partai-partai politik Indonesia dengan ketua M.H. Thamrin. 2. GAPI mengajukan tuntutan politik kepada pemerintah kolonial Belanda. 3. Tuntutan utamanya dikenal sebagai Indonesia Berparlemen, yaitu agar Indonesia memiliki parlemen sendiri yang berdaulat. 4. Jadi jawabannya Indonesia Berparlemen." },
    { q: "Majelis Islam A'la Indonesia (MIAI) yang didirikan tahun 1937 adalah federasi organisasi-organisasi ....", options: ["nasionalis sekuler", "Islam", "pemuda daerah", "buruh dan tani"], answer: 1, solution: "1. Pada tahun 1937 organisasi-organisasi Islam di Indonesia merasa perlu bersatu dalam satu wadah. 2. Mereka membentuk Majelis Islam A'la Indonesia atau MIAI sebagai federasi organisasi Islam. 3. Tokoh-tokohnya antara lain K.H. Mas Mansyur dari Muhammadiyah dan K.H. Wahab Hasbullah dari NU. 4. Jadi jawabannya Islam." },
    { q: "Parindra dipimpin oleh dr. Sutomo, sedangkan Gerindo dipimpin oleh ....", options: ["Moh. Hatta", "Sartono", "Soekarno", "Ki Hajar Dewantara"], answer: 1, solution: "1. Parindra (Partai Indonesia Raya) adalah fusi Budi Utomo dan PBI yang dipimpin dr. Sutomo. 2. Gerindo (Gerakan Rakyat Indonesia) didirikan pada tahun 1937 sebagai partai berhaluan nasionalis. 3. Gerindo dipimpin oleh Sartono bersama tokoh-tokoh seperti A.K. Gani dan Muhammad Yamin. 4. Jadi jawabannya Sartono." },
    { q: "Tokoh Betawi yang gigih menyuarakan kepentingan rakyat Indonesia di Volksraad adalah ....", options: ["Mohammad Husni Thamrin", "Abdul Muis", "Sutardjo Kartohadikusumo", "Wiranatakusumah"], answer: 0, solution: "1. Volksraad adalah dewan rakyat bentukan pemerintah kolonial Belanda. 2. Mohammad Husni Thamrin menjadi anggotanya dan memanfaatkannya sebagai mimbar perjuangan. 3. Ia gigih mengkritik kebijakan kolonial dan membela nasib rakyat Indonesia. 4. Jadi jawabannya Mohammad Husni Thamrin." },
    { q: "Kongres Pemuda I yang berlangsung pada tahun 1926 diketuai oleh ....", options: ["Sugondo Djojopuspito", "M. Tabrani", "Muhammad Yamin", "Amir Syarifuddin"], answer: 1, solution: "1. Kongres Pemuda I berlangsung di Jakarta pada 30 April sampai 2 Mei 1926. 2. Kongres ini diketuai oleh M. Tabrani. 3. Salah satu hasil pentingnya adalah gagasan menjadikan bahasa Indonesia sebagai bahasa persatuan. 4. Jadi jawabannya M. Tabrani." },
    { q: "Ketua Kongres Pemuda II yang menghasilkan Sumpah Pemuda pada 28 Oktober 1928 adalah ....", options: ["M. Tabrani", "Sugondo Djojopuspito", "W.R. Supratman", "Muhammad Yamin"], answer: 1, solution: "1. Kongres Pemuda II berlangsung di Jakarta pada 27-28 Oktober 1928. 2. Kongres ini diketuai oleh Sugondo Djojopuspito dari PPPI. 3. Hasil kongres ini adalah ikrar Sumpah Pemuda yang menjadi tonggak persatuan bangsa Indonesia. 4. Jadi jawabannya Sugondo Djojopuspito." },
    { q: "Surat kabar Medan Priyayi yang terbit tahun 1907 didirikan oleh tokoh yang dijuluki Bapak Pers Indonesia, yaitu ....", options: ["Tirto Adhi Soerjo", "Douwes Dekker", "Marco Kartodikromo", "Suwardi Suryaningrat"], answer: 0, solution: "1. Tirto Adhi Soerjo adalah wartawan pribumi pelopor pers Indonesia. 2. Ia mendirikan surat kabar Medan Priyayi pada tahun 1907 sebagai corong suara rakyat pribumi. 3. Perjuangannya melalui pers membuat ia dijuluki Bapak Pers Indonesia. 4. Jadi jawabannya Tirto Adhi Soerjo." },
    { q: "Pemberontakan tentara PETA di Blitar pada 14 Februari 1945 dipimpin oleh ....", options: ["Soedirman", "Supriyadi", "Gatot Subroto", "Urip Sumoharjo"], answer: 1, solution: "1. PETA adalah tentara sukarela bentukan Jepang yang anggotanya para pemuda Indonesia. 2. Pada 14 Februari 1945 pasukan PETA di Blitar memberontak melawan Jepang. 3. Pemberontakan ini dipimpin oleh Shodancho Supriyadi yang kemudian menghilang dan tidak diketahui nasibnya. 4. Jadi jawabannya Supriyadi." },
    { q: "Tiga tokoh yang menyampaikan pidato tentang dasar negara pada sidang I BPUPKI adalah ....", options: ["Soekarno, Hatta, dan Sjahrir", "Moh. Yamin, Mr. Soepomo, dan Soekarno", "Radjiman, Sartono, dan Thamrin", "Yamin, Hatta, dan Agus Salim"], answer: 1, solution: "1. Sidang I BPUPKI pada 29 Mei sampai 1 Juni 1945 membahas dasar negara Indonesia merdeka. 2. Tiga tokoh menyampaikan pidatonya, yaitu Moh. Yamin pada 29 Mei, Mr. Soepomo pada 31 Mei, dan Soekarno pada 1 Juni 1945. 3. Pidato Soekarno pada 1 Juni itulah yang melahirkan istilah Pancasila. 4. Jadi jawabannya Moh. Yamin, Mr. Soepomo, dan Soekarno." },
    { q: "Pidato Soekarno tentang dasar negara yang kemudian diperingati sebagai Hari Lahir Pancasila disampaikan pada ....", options: ["29 Mei 1945", "1 Juni 1945", "22 Juni 1945", "17 Agustus 1945"], answer: 1, solution: "1. Dalam sidang I BPUPKI, Soekarno mendapat giliran berpidato tentang dasar negara. 2. Pidatonya disampaikan pada 1 Juni 1945 dan untuk pertama kalinya mengusulkan nama Pancasila. 3. Tanggal ini kemudian diperingati setiap tahun sebagai Hari Lahir Pancasila. 4. Jadi jawabannya 1 Juni 1945." },
    { q: "Panitia Sembilan yang merumuskan Piagam Jakarta dibentuk dan mencapai kesepakatan pada tanggal ....", options: ["1 Juni 1945", "22 Juni 1945", "10 Juli 1945", "7 Agustus 1945"], answer: 1, solution: "1. Setelah sidang I BPUPKI dibentuk panitia kecil beranggotakan sembilan orang yang diketuai Soekarno. 2. Panitia ini bertugas merumuskan dasar negara yang disepakati bersama. 3. Hasilnya adalah Piagam Jakarta yang disepakati pada 22 Juni 1945. 4. Jadi jawabannya 22 Juni 1945." },
    { q: "Tujuh kata dalam Piagam Jakarta yang dicoret pada sidang PPKI 18 Agustus 1945 adalah ....", options: ["Ketuhanan Yang Maha Esa", "dengan kewajiban menjalankan syariat Islam bagi pemeluk-pemeluknya", "kemanusiaan yang adil dan beradab", "kerakyatan yang dipimpin oleh hikmat kebijaksanaan"], answer: 1, solution: "1. Piagam Jakarta memuat sila pertama yang berbunyi Ketuhanan dengan kewajiban menjalankan syariat Islam bagi pemeluk-pemeluknya. 2. Rumusan tujuh kata terakhir itu dikhawatirkan memecah persatuan bangsa. 3. Atas usul Mohammad Hatta, sidang PPKI 18 Agustus 1945 mencoret tujuh kata tersebut. 4. Jadi jawabannya dengan kewajiban menjalankan syariat Islam bagi pemeluk-pemeluknya." },
    { q: "Sidang II BPUPKI yang membahas rancangan Undang-Undang Dasar berlangsung pada ....", options: ["29 Mei sampai 1 Juni 1945", "22 Juni 1945", "10 sampai 17 Juli 1945", "18 Agustus 1945"], answer: 2, solution: "1. BPUPKI mengadakan dua kali sidang resmi sebelum dibubarkan Jepang. 2. Sidang I pada 29 Mei sampai 1 Juni 1945 membahas dasar negara. 3. Sidang II pada 10 sampai 17 Juli 1945 membahas rancangan Undang-Undang Dasar dan bentuk negara. 4. Jadi jawabannya 10 sampai 17 Juli 1945." },
    { q: "PPKI atau Panitia Persiapan Kemerdekaan Indonesia dibentuk pada 7 Agustus 1945 dengan ketua dan wakil ketua ....", options: ["Hatta dan Soekarno", "Soekarno dan Hatta", "Radjiman dan Soepomo", "Sjahrir dan Amir Syarifuddin"], answer: 1, solution: "1. Setelah BPUPKI dibubarkan, Jepang membentuk PPKI pada 7 Agustus 1945. 2. PPKI bertugas mempersiapkan segala sesuatu untuk kemerdekaan Indonesia. 3. Ketuanya adalah Ir. Soekarno dan wakil ketuanya Drs. Moh. Hatta. 4. Jadi jawabannya Soekarno dan Hatta." },
    { q: "Peristiwa Rengasdengklok pada 16 Agustus 1945 terjadi karena golongan muda ....", options: ["menolak kemerdekaan Indonesia", "mendesak Soekarno-Hatta segera memproklamasikan kemerdekaan", "ingin bekerja sama dengan Jepang", "menuntut Soekarno mundur dari PPKI"], answer: 1, solution: "1. Jepang telah menyerah kepada Sekutu pada 15 Agustus 1945 sehingga terjadi kekosongan kekuasaan. 2. Golongan muda seperti Sukarni, Wikana, dan Chaerul Saleh menghendaki proklamasi segera tanpa campur tangan Jepang. 3. Mereka membawa Soekarno dan Hatta ke Rengasdengklok agar tidak terpengaruh oleh Jepang. 4. Jadi jawabannya mendesak Soekarno-Hatta segera memproklamasikan kemerdekaan." },
    { q: "Naskah teks proklamasi dirumuskan pada dini hari 17 Agustus 1945 di ....", options: ["Gedung Merdeka Bandung", "rumah Laksamana Maeda di Jakarta", "Istana Merdeka", "Gedung Pancasila"], answer: 1, solution: "1. Setelah peristiwa Rengasdengklok, Soekarno dan Hatta kembali ke Jakarta. 2. Perumusan teks proklamasi dilakukan di rumah Laksamana Maeda di Jalan Imam Bonjol Nomor 1 Jakarta. 3. Teks dirumuskan oleh Soekarno, Hatta, dan Ahmad Soebardjo lalu diketik oleh Sayuti Melik. 4. Jadi jawabannya rumah Laksamana Maeda di Jakarta." },
    { q: "Dua pengibar bendera Sang Saka Merah Putih pada upacara proklamasi 17 Agustus 1945 adalah ....", options: ["Latief Hendraningrat dan Suhud", "Soekarno dan Hatta", "Sukarni dan Wikana", "Sayuti Melik dan B.M. Diah"], answer: 0, solution: "1. Upacara proklamasi dilaksanakan di Jalan Pegangsaan Timur Nomor 56 Jakarta pada 17 Agustus 1945. 2. Bendera Sang Saka Merah Putih yang dijahit Fatmawati dikibarkan dalam upacara itu. 3. Dua pengibar benderanya adalah Latief Hendraningrat dan Suhud Sastro Kusumo. 4. Jadi jawabannya Latief Hendraningrat dan Suhud." },
    { q: "Kalimat pembuka teks proklamasi kemerdekaan Indonesia berbunyi ....", options: ["Atas berkat rahmat Allah Yang Maha Kuasa", "Kami bangsa Indonesia dengan ini menjatakan kemerdekaan Indonesia", "Bahwa sesungguhnya kemerdekaan itu ialah hak segala bangsa", "Merdeka atau mati"], answer: 1, solution: "1. Teks proklamasi terdiri atas dua alinea yang singkat dan padat. 2. Alinea pertama berbunyi Kami bangsa Indonesia dengan ini menjatakan kemerdekaan Indonesia. 3. Kalimat ini menegaskan bahwa kemerdekaan dinyatakan atas nama seluruh bangsa Indonesia. 4. Jadi jawabannya Kami bangsa Indonesia dengan ini menjatakan kemerdekaan Indonesia." },
    { q: "Berita proklamasi kemerdekaan 17 Agustus 1945 dapat tersebar ke seluruh Indonesia terutama melalui ....", options: ["telegram resmi pemerintah Jepang", "radio, surat kabar, dan para pemuda penyebar berita", "utusan pemerintah Belanda", "kantor berita asing"], answer: 1, solution: "1. Jepang berusaha merahasiakan berita kekalahannya dan melarang penyebaran berita proklamasi. 2. Namun para pemuda pejuang menyebarluaskan berita melalui siaran radio dan surat kabar. 3. Para pemuda juga menyebarkan berita dari mulut ke mulut hingga ke daerah-daerah. 4. Jadi jawabannya radio, surat kabar, dan para pemuda penyebar berita." },
    { q: "Pada sidang 19 Agustus 1945 PPKI membagi Indonesia menjadi 8 provinsi lengkap dengan gubernurnya, sedangkan pada sidang 22 Agustus 1945 PPKI membentuk ....", options: ["Tentara Keamanan Rakyat", "Komite Nasional Indonesia Pusat atau KNIP", "Dewan Pertimbangan Agung", "Mahkamah Agung"], answer: 1, solution: "1. PPKI bersidang beberapa kali setelah proklamasi untuk melengkapi alat-alat negara. 2. Pada sidang 19 Agustus 1945 PPKI membagi wilayah Indonesia menjadi 8 provinsi dan mengangkat gubernurnya. 3. Pada sidang 22 Agustus 1945 PPKI membentuk Komite Nasional Indonesia Pusat atau KNIP sebagai badan pembantu presiden. 4. Jadi jawabannya Komite Nasional Indonesia Pusat atau KNIP." },
    { q: "Pertempuran Surabaya yang diperingati sebagai Hari Pahlawan terjadi pada ....", options: ["10 November 1945", "17 Agustus 1945", "20 November 1946", "1 Maret 1949"], answer: 0, solution: "1. Setelah insiden Hotel Yamato dan tewasnya Brigjen Mallaby, Sekutu mengeluarkan ultimatum agar para pejuang Surabaya menyerah. 2. Para pejuang menolak dan pada 10 November 1945 meletus pertempuran besar melawan Sekutu di Surabaya. 3. Untuk mengenang keberanian para pejuang, tanggal 10 November diperingati sebagai Hari Pahlawan. 4. Jadi jawabannya 10 November 1945." },
    { q: "Tokoh yang membakar semangat arek-arek Suroboyo melalui siaran radio saat pertempuran Surabaya 1945 adalah ....", options: ["Bung Tomo", "Jenderal Sudirman", "Moh. Hatta", "Sutan Sjahrir"], answer: 0, solution: "1. Pada pertempuran Surabaya, para pejuang membutuhkan sosok orator yang membangkitkan semangat. 2. Sutomo atau Bung Tomo berpidato berapi-api lewat Radio Pemberontakan yang disiarkan ke seluruh kota. 3. Pidatonya yang terkenal menyerukan perlawanan habis-habisan melawan Sekutu. 4. Jadi jawabannya Bung Tomo." },
    { q: "Tewasnya Brigjen A.W.S. Mallaby pada 30 Oktober 1945 menjadi salah satu pemicu ....", options: ["Pertempuran Surabaya 10 November 1945", "Palagan Ambarawa", "Bandung Lautan Api", "Agresi Militer Belanda I"], answer: 0, solution: "1. Brigjen Mallaby adalah komandan pasukan Sekutu di Surabaya yang tewas dalam insiden pada 30 Oktober 1945. 2. Kematian Mallaby membuat Sekutu marah dan mengeluarkan ultimatum agar para pejuang menyerahkan senjata. 3. Ultimatum itu ditolak sehingga meletus pertempuran besar pada 10 November 1945. 4. Jadi jawabannya Pertempuran Surabaya 10 November 1945." },
    { q: "Pertempuran Palagan Ambarawa yang berhasil mengusir pasukan Sekutu dipimpin oleh ....", options: ["Jenderal Sudirman", "Bung Tomo", "Mohammad Toha", "I Gusti Ngurah Rai"], answer: 0, solution: "1. Pada akhir 1945 pasukan Sekutu menduduki Ambarawa dan sekitarnya di Jawa Tengah. 2. Pasukan Indonesia di bawah Panglima Besar Jenderal Sudirman melancarkan serangan balasan. 3. Kemenangan pada 15 Desember 1945 itu dikenal sebagai Palagan Ambarawa. 4. Jadi jawabannya Jenderal Sudirman." },
    { q: "Peristiwa pembumihangusan kota Bandung oleh para pejuang pada 23 Maret 1946 dikenal sebagai ....", options: ["Bandung Lautan Api", "Pertempuran Medan Area", "Puputan Margarana", "Serangan Umum 1 Maret"], answer: 0, solution: "1. Sekutu mengeluarkan ultimatum agar para pejuang meninggalkan Bandung. 2. Para pejuang memilih membumihanguskan kota agar tidak dikuasai musuh, dipimpin Mohammad Toha. 3. Kobaran api yang membakar Bandung pada 23 Maret 1946 itu dikenal sebagai Bandung Lautan Api. 4. Jadi jawabannya Bandung Lautan Api." },
    { q: "Perang puputan di desa Margarana, Bali, pada 20 November 1946 dipimpin oleh ....", options: ["I Gusti Ngurah Rai", "Mohammad Toha", "Bung Tomo", "Jenderal Sudirman"], answer: 0, solution: "1. Pasukan Ciung Wanara dari Bali berhadapan dengan Belanda di desa Margarana. 2. Komandannya, I Gusti Ngurah Rai, memilih perang habis-habisan (puputan) sampai titik darah penghabisan. 3. Peristiwa 20 November 1946 itu dikenang sebagai Puputan Margarana. 4. Jadi jawabannya I Gusti Ngurah Rai." },
    { q: "Ketua delegasi Indonesia dalam Perjanjian Linggarjati 1946 adalah ....", options: ["Sutan Sjahrir", "Lord Killearn", "Amir Sjarifuddin", "Moh. Hatta"], answer: 0, solution: "1. Perjanjian Linggarjati ditandatangani pada 15 November 1946 dengan Inggris sebagai penengah. 2. Delegasi Indonesia dipimpin oleh Perdana Menteri Sutan Sjahrir. 3. Lord Killearn adalah utusan Inggris yang menjadi mediator, bukan ketua delegasi Indonesia. 4. Jadi jawabannya Sutan Sjahrir." },
    { q: "Agresi Militer Belanda I dilancarkan pada ....", options: ["21 Juli 1947", "19 Desember 1948", "27 Desember 1949", "17 Januari 1948"], answer: 0, solution: "1. Belanda merasa dirugikan oleh Perjanjian Linggarjati dan menuduh Indonesia melanggarnya. 2. Pada 21 Juli 1947 Belanda melancarkan Agresi Militer I yang disebut Operatie Product. 3. Tanggal 19 Desember 1948 adalah Agresi Militer II dan 17 Januari 1948 adalah Perjanjian Renville. 4. Jadi jawabannya 21 Juli 1947." },
    { q: "Perjanjian Renville ditandatangani pada 17 Januari 1948 di atas kapal perang Amerika Serikat dengan delegasi Indonesia dipimpin oleh ....", options: ["Amir Sjarifuddin", "Sutan Sjahrir", "Moh. Hatta", "Syafruddin Prawiranegara"], answer: 0, solution: "1. Perundingan Renville berlangsung di atas kapal USS Renville yang berlabuh di Teluk Jakarta. 2. Delegasi Indonesia dipimpin oleh Perdana Menteri Amir Sjarifuddin. 3. Hasilnya antara lain garis demarkasi Van Mook yang merugikan Indonesia. 4. Jadi jawabannya Amir Sjarifuddin." },
    { q: "Ketika Yogyakarta diduduki Belanda pada Agresi Militer II, pemerintahan darurat bernama PDRI didirikan di Bukittinggi dan dipimpin oleh ....", options: ["Syafruddin Prawiranegara", "Moh. Hatta", "Sutan Sjahrir", "Ir. Soekarno"], answer: 0, solution: "1. Agresi Militer II pada 19 Desember 1948 menduduki Yogyakarta dan menangkap Soekarno-Hatta. 2. Sebelum ditangkap, mereka memberi mandat agar dibentuk pemerintahan darurat. 3. Di Bukittinggi berdiri Pemerintahan Darurat Republik Indonesia (PDRI) yang dipimpin Syafruddin Prawiranegara. 4. Jadi jawabannya Syafruddin Prawiranegara." },
    { q: "Serangan Umum 1 Maret 1949 terhadap Yogyakarta yang diduduki Belanda dipimpin oleh ....", options: ["Suharto", "Jenderal Sudirman", "Sri Sultan Hamengkubuwono IX", "Moh. Hatta"], answer: 0, solution: "1. Serangan Umum 1 Maret 1949 bertujuan menunjukkan kepada dunia bahwa Indonesia masih ada dan berdaulat. 2. Serangan dipimpin oleh Letkol Suharto sebagai komandan operasi. 3. Sri Sultan Hamengkubuwono IX adalah penggagas dan koordinator politiknya, bukan komandan lapangan. 4. Jadi jawabannya Suharto." },
    { q: "Perjanjian Roem-Royen yang menghasilkan kembalinya pemerintahan RI ke Yogyakarta ditandatangani pada ....", options: ["7 Mei 1949", "17 Januari 1948", "15 November 1946", "23 Agustus 1949"], answer: 0, solution: "1. Setelah Agresi Militer II, PBB menekan Belanda agar berunding kembali dengan Indonesia. 2. Perundingan antara Moh. Roem (Indonesia) dan J.H. van Roijen (Belanda) menghasilkan kesepakatan pada 7 Mei 1949. 3. Isinya antara lain kembalinya pemerintahan RI ke Yogyakarta dan penghentian tembak-menembak. 4. Jadi jawabannya 7 Mei 1949." },
    { q: "Ketua delegasi Indonesia dalam Konferensi Meja Bundar (KMB) di Den Haag tahun 1949 adalah ....", options: ["Moh. Hatta", "Sutan Sjahrir", "Moh. Roem", "Amir Sjarifuddin"], answer: 0, solution: "1. KMB berlangsung pada 23 Agustus sampai 2 November 1949 di Den Haag, Belanda. 2. Delegasi Republik Indonesia dipimpin oleh Wakil Presiden Moh. Hatta. 3. Hasilnya Belanda mengakui kedaulatan Indonesia dengan penyerahan kedaulatan pada 27 Desember 1949. 4. Jadi jawabannya Moh. Hatta." },
    { q: "Kembalinya Indonesia dari negara serikat (RIS) menjadi NKRI pada 17 Agustus 1950 diawali oleh ....", options: ["Mosi Integral Moh. Natsir", "Dekrit Presiden 5 Juli 1959", "Perjanjian Roem-Royen", "Maklumat Wakil Presiden"], answer: 0, solution: "1. Bentuk negara serikat hasil KMB ternyata tidak sesuai dengan cita-cita persatuan. 2. Pada 3 April 1950 Moh. Natsir mengajukan Mosi Integral di parlemen RIS agar negara-negara bagian bergabung kembali. 3. Mosi itu disetujui sehingga pada 17 Agustus 1950 Indonesia kembali menjadi negara kesatuan (NKRI). 4. Jadi jawabannya Mosi Integral Moh. Natsir." },
    { q: "Kabinet pertama pada masa Demokrasi Liberal (1950-1959) adalah kabinet ....", options: ["Natsir", "Sukiman", "Wilopo", "Djuanda"], answer: 0, solution: "1. Masa Demokrasi Liberal ditandai sistem parlementer dengan kabinet yang silih berganti. 2. Kabinet pertama dibentuk oleh Mohammad Natsir dari Masyumi pada September 1950. 3. Kabinet Sukiman, Wilopo, dan Djuanda adalah kabinet-kabinet berikutnya pada masa yang sama. 4. Jadi jawabannya Natsir." },
    { q: "Pemilu 1955 yang merupakan pemilu pertama di Indonesia dilaksanakan dalam dua tahap pada tanggal ....", options: ["29 September dan 15 Desember 1955", "17 Agustus dan 27 Desember 1955", "1 Juni dan 5 Juli 1955", "10 November dan 20 Mei 1955"], answer: 0, solution: "1. Pemilu 1955 adalah pemilu pertama dalam sejarah Indonesia. 2. Tahap pertama pada 29 September 1955 untuk memilih anggota DPR. 3. Tahap kedua pada 15 Desember 1955 untuk memilih anggota Konstituante yang bertugas menyusun UUD. 4. Jadi jawabannya 29 September dan 15 Desember 1955." },
    { q: "Nasakom yang menjadi landasan Demokrasi Terpimpin merupakan singkatan dari ....", options: ["Nasionalis, Agama, Komunis", "Nasionalisme, Anti-kolonialisme, Komunisme", "Negara, Agama, Komando", "Nasional, Aman, Kompak"], answer: 0, solution: "1. Demokrasi Terpimpin adalah gagasan Soekarno untuk menyatukan kekuatan-kekuatan politik. 2. Nasakom adalah singkatan dari Nasionalis, Agama, dan Komunis. 3. Konsep ini menjadi landasan politik Soekarno pada masa Demokrasi Terpimpin. 4. Jadi jawabannya Nasionalis, Agama, Komunis." },
    { q: "Manipol/USDEK yang menjadi haluan negara pada masa Demokrasi Terpimpin dicetuskan oleh ....", options: ["Soekarno", "Moh. Hatta", "Sutan Sjahrir", "Soeharto"], answer: 0, solution: "1. Manipol adalah Manifesto Politik Republik Indonesia yang disampaikan Soekarno pada 17 Agustus 1959. 2. USDEK adalah penjabarannya: UUD 1945, Sosialisme Indonesia, Demokrasi Terpimpin, Ekonomi Terpimpin, dan Kepribadian Indonesia. 3. Manipol/USDEK menjadi garis haluan negara pada masa Demokrasi Terpimpin. 4. Jadi jawabannya Soekarno." },
    { q: "Pemberontakan DI/TII di Jawa Barat yang bertujuan mendirikan Negara Islam Indonesia dipimpin oleh ....", options: ["Kartosuwiryo", "Ahmad Husein", "Ventje Sumual", "Soumokil"], answer: 0, solution: "1. DI/TII (Darul Islam/Tentara Islam Indonesia) muncul pada 1948 di Jawa Barat. 2. Pemberontakan ini dipimpin oleh Sekarmadji Maridjan Kartosuwiryo yang memproklamasikan Negara Islam Indonesia. 3. Pemberontakan berakhir setelah Kartosuwiryo ditangkap pada 1962. 4. Jadi jawabannya Kartosuwiryo." },
    { q: "Pemberontakan PRRI di Sumatera pada 1958 dipimpin oleh ....", options: ["Ahmad Husein", "Ventje Sumual", "Soumokil", "Andi Azis"], answer: 0, solution: "1. PRRI (Pemerintahan Revolusioner Republik Indonesia) diproklamasikan pada 15 Februari 1958 di Padang, Sumatera Barat. 2. Pemberontakan ini dipimpin oleh Letkol Ahmad Husein. 3. Di Sulawesi, pemberontakan sejenis bernama Permesta dipimpin Ventje Sumual. 4. Jadi jawabannya Ahmad Husein." },
    { q: "Pemberontakan RMS (Republik Maluku Selatan) yang diproklamasikan pada 25 April 1950 dipimpin oleh ....", options: ["Soumokil", "Andi Azis", "Kartosuwiryo", "Ahmad Husein"], answer: 0, solution: "1. RMS diproklamasikan pada 25 April 1950 di Ambon. 2. Pemimpinnya adalah dr. Soumokil. 3. Pemberontakan ini ditumpas oleh TNI dan Soumokil ditangkap pada 1963. 4. Jadi jawabannya Soumokil." },
    { q: "Operasi Dwikora dilancarkan Soekarno sebagai bentuk konfrontasi terhadap ....", options: ["Malaysia", "Belanda", "Inggris", "Portugis"], answer: 0, solution: "1. Indonesia menentang pembentukan Federasi Malaysia yang dianggap proyek neokolonialisme Inggris. 2. Soekarno mencetuskan Dwi Komando Rakyat (Dwikora) pada 3 Mei 1964 dengan seruan Ganyang Malaysia. 3. Konfrontasi ini berakhir setelah jatuhnya Soekarno dan ditandatangani perdamaian pada 1966. 4. Jadi jawabannya Malaysia." },
    { q: "Supersemar yang menjadi tonggak awal peralihan ke Orde Baru dikeluarkan pada ....", options: ["11 Maret 1966", "30 September 1965", "5 Juli 1959", "21 Mei 1998"], answer: 0, solution: "1. Setelah peristiwa G30S 1965, situasi politik dan keamanan semakin tidak menentu. 2. Pada 11 Maret 1966 Soekarno mengeluarkan Surat Perintah Sebelas Maret (Supersemar) kepada Letjen Soeharto. 3. Surat ini memberi wewenang kepada Soeharto mengambil langkah pengamanan, menjadi awal Orde Baru. 4. Jadi jawabannya 11 Maret 1966." },
    { q: "Tritura (Tri Tuntutan Rakyat) yang disuarakan mahasiswa pada Januari 1966 berisi tiga tuntutan, salah satunya ....", options: ["pembubaran PKI", "pengakuan kedaulatan", "kembali ke UUD 1945", "pembentukan RIS"], answer: 0, solution: "1. Krisis politik pasca G30S memicu aksi demonstrasi mahasiswa pada Januari 1966. 2. Mereka menyuarakan Tri Tuntutan Rakyat (Tritura): bubarkan PKI, rombak Kabinet Dwikora, dan turunkan harga. 3. Tuntutan ini menjadi tekanan politik yang mempercepat lahirnya Orde Baru. 4. Jadi jawabannya pembubaran PKI." },
    { q: "Landasan hukum pembubaran PKI dan pelarangan ajaran komunisme pada masa Orde Baru adalah ....", options: ["TAP MPRS No. XXV/MPRS/1966", "UUD 1945 Pasal 28", "UU No. 5 Tahun 1974", "Keputusan Presiden No. 10"], answer: 0, solution: "1. Setelah G30S, PKI dianggap bertanggung jawab atas pemberontakan. 2. MPRS mengeluarkan Ketetapan No. XXV/MPRS/1966 tentang pembubaran PKI dan larangan penyebaran ajaran komunisme. 3. Ketetapan ini menjadi dasar hukum pemberantasan PKI pada masa Orde Baru. 4. Jadi jawabannya TAP MPRS No. XXV/MPRS/1966." },
    { q: "Penyederhanaan partai politik pada 1973 menghasilkan tiga kekuatan politik, yaitu ....", options: ["PPP, PDI, dan Golkar", "PNI, Masyumi, dan PKI", "Demokrat, Golkar, dan PKS", "PDI, PPP, dan NasDem"], answer: 0, solution: "1. Orde Baru menyederhanakan partai politik untuk menciptakan stabilitas. 2. Pada 1973 partai-partai Islam difusi menjadi PPP dan partai-partai nasionalis menjadi PDI, sementara Golkar menjadi kekuatan tersendiri. 3. Ketiga kekuatan inilah yang menjadi peserta pemilu-pemilu Orde Baru. 4. Jadi jawabannya PPP, PDI, dan Golkar." },
    { q: "Peristiwa Malari yang terjadi pada 15 Januari 1974 dilatarbelakangi oleh ....", options: ["protes terhadap dominasi modal asing, terutama Jepang", "tuntutan pembubaran PKI", "penolakan hasil pemilu 1971", "tuntutan pemisahan Timor Timur"], answer: 0, solution: "1. Malari adalah singkatan dari Malapetaka 15 Januari 1974. 2. Peristiwa ini berupa kerusuhan saat kunjungan Perdana Menteri Jepang Tanaka ke Jakarta. 3. Mahasiswa dan masyarakat memprotes dominasi modal asing, terutama Jepang, dalam perekonomian Indonesia. 4. Jadi jawabannya protes terhadap dominasi modal asing, terutama Jepang." },
    { q: "Tragedi Trisakti yang menjadi pemicu gelombang reformasi terjadi pada ....", options: ["12 Mei 1998", "21 Mei 1998", "11 Maret 1966", "15 Januari 1974"], answer: 0, solution: "1. Krisis moneter memicu demonstrasi besar mahasiswa menuntut Soeharto mundur. 2. Pada 12 Mei 1998 aparat menembaki demonstran di Universitas Trisakti Jakarta hingga empat mahasiswa gugur. 3. Tragedi ini memicu kerusuhan besar dan mempercepat lengsernya Soeharto pada 21 Mei 1998. 4. Jadi jawabannya 12 Mei 1998." },
    { q: "UUD 1945 telah diamandemen sebanyak ....", options: ["4 kali", "2 kali", "3 kali", "5 kali"], answer: 0, solution: "1. Era reformasi menuntut pembatasan kekuasaan presiden dan penguatan demokrasi. 2. UUD 1945 diamandemen secara bertahap pada tahun 1999, 2000, 2001, dan 2002. 3. Hasilnya antara lain pembatasan masa jabatan presiden dua periode dan pemilihan presiden langsung. 4. Jadi jawabannya 4 kali." },
    { q: "Komisi Pemberantasan Korupsi (KPK) dibentuk berdasarkan ....", options: ["UU No. 30 Tahun 2002", "UU No. 22 Tahun 1999", "TAP MPR No. XI/1998", "Keputusan Presiden No. 44"], answer: 0, solution: "1. Pemberantasan korupsi menjadi salah satu agenda utama reformasi. 2. KPK dibentuk sebagai lembaga independen berdasarkan UU No. 30 Tahun 2002. 3. UU No. 22 Tahun 1999 mengatur tentang otonomi daerah, bukan KPK. 4. Jadi jawabannya UU No. 30 Tahun 2002." },
    { q: "Dokumen yang menjadi tonggak Revolusi Amerika dan ditandatangani pada 4 Juli 1776 adalah ....", options: ["Declaration of Independence", "Declaration des Droits de l'Homme", "Magna Carta", "Bill of Rights"], answer: 0, solution: "1. Koloni-koloni Inggris di Amerika memberontak karena pajak dan penindasan. 2. Pada 4 Juli 1776 para wakil koloni menandatangani Declaration of Independence yang menyatakan kemerdekaan dari Inggris. 3. George Washington kemudian memimpin perang kemerdekaan dan menjadi presiden pertama AS. 4. Jadi jawabannya Declaration of Independence." },
    { q: "Peristiwa penyerbuan penjara Bastille yang menjadi simbol meletusnya Revolusi Perancis terjadi pada ....", options: ["14 Juli 1789", "4 Juli 1776", "7 November 1917", "1 September 1939"], answer: 0, solution: "1. Rakyat Perancis memberontak terhadap monarki absolut Raja Louis XVI. 2. Pada 14 Juli 1789 massa menyerbu penjara Bastille, simbol kekuasaan raja. 3. Revolusi ini mengusung semboyan liberte, egalite, fraternite dan melahirkan Declaration des Droits de l'Homme. 4. Jadi jawabannya 14 Juli 1789." },
    { q: "Tokoh yang memimpin kaum Bolshevik dalam Revolusi Rusia 1917 adalah ....", options: ["Vladimir Lenin", "Joseph Stalin", "Karl Marx", "Leon Trotsky"], answer: 0, solution: "1. Kekalahan Rusia dalam Perang Dunia I dan krisis ekonomi memicu revolusi. 2. Kaum Bolshevik di bawah pimpinan Vladimir Lenin merebut kekuasaan pada Revolusi Oktober 1917. 3. Revolusi ini melahirkan negara komunis pertama, Uni Soviet. 4. Jadi jawabannya Vladimir Lenin." },
    { q: "Dua blok aliansi yang saling berhadapan dalam Perang Dunia I adalah ....", options: ["Triple Alliance melawan Triple Entente", "Blok Poros melawan Sekutu", "NATO melawan Pakta Warsawa", "Blok Barat melawan Blok Timur"], answer: 0, solution: "1. Sebelum PD I, negara-negara Eropa terpecah dalam dua aliansi militer. 2. Triple Alliance terdiri dari Jerman, Austria-Hongaria, dan Italia. 3. Triple Entente terdiri dari Inggris, Perancis, dan Rusia. 4. Jadi jawabannya Triple Alliance melawan Triple Entente." },
    { q: "Perang Dunia II dimulai ketika Jerman menyerbu Polandia pada ....", options: ["1 September 1939", "28 Juni 1914", "7 Desember 1941", "6 Agustus 1945"], answer: 0, solution: "1. Jerman di bawah Hitler melakukan ekspansi wilayah di Eropa. 2. Pada 1 September 1939 Jerman menyerbu Polandia. 3. Inggris dan Perancis kemudian menyatakan perang terhadap Jerman sehingga meletuslah Perang Dunia II. 4. Jadi jawabannya 1 September 1939." },
    { q: "Negara-negara yang tergabung dalam Blok Poros pada Perang Dunia II adalah ....", options: ["Jerman, Italia, dan Jepang", "Inggris, Perancis, dan Rusia", "Amerika Serikat, Inggris, dan Uni Soviet", "Jerman, Austria-Hongaria, dan Turki"], answer: 0, solution: "1. Perang Dunia II mempertarungkan dua blok besar. 2. Blok Poros terdiri dari Jerman, Italia, dan Jepang. 3. Blok Sekutu terdiri dari Inggris, Perancis, Uni Soviet, dan Amerika Serikat. 4. Jadi jawabannya Jerman, Italia, dan Jepang." },
    { q: "Runtuhnya Uni Soviet pada 1991 diawali oleh kebijakan reformasi Mikhail Gorbachev yang dikenal sebagai ....", options: ["glasnost dan perestroika", "truman dan marshall", "nasakom dan manipol", "dwikora dan tritura"], answer: 0, solution: "1. Uni Soviet mengalami kemandekan ekonomi dan politik pada 1980-an. 2. Mikhail Gorbachev melancarkan glasnost (keterbukaan) dan perestroika (restrukturisasi). 3. Kebijakan ini justru mempercepat disintegrasi hingga Uni Soviet bubar pada 1991 dan Perang Dingin berakhir. 4. Jadi jawabannya glasnost dan perestroika." },
    { q: "Gerakan Non-Blok didirikan pada Konferensi Beograd tahun 1961 atas prakarsa tokoh-tokoh berikut, kecuali ....", options: ["Harry Truman", "Soekarno", "Gamal Abdel Nasser", "Josip Broz Tito"], answer: 0, solution: "1. Gerakan Non-Blok didirikan pada 1961 di Beograd, Yugoslavia. 2. Tokoh pendirinya antara lain Soekarno (Indonesia), Nasser (Mesir), Tito (Yugoslavia), Nehru (India), dan Nkrumah (Ghana). 3. Harry Truman adalah presiden Amerika Serikat pencetus Doktrin Truman, bukan pendiri Gerakan Non-Blok. 4. Jadi jawabannya Harry Truman." }
  ]
};